COLLDATA("sharhsunnaur","ur",[[2514,"ام المومنین سیدہ عائشہ رضی اللہ عنہا سے مروی ہے وہ اسے مرفوعاً بیان کرتی ہیں: ’’خائن مرد اور خائن عورت کی گواہی جائز نہیں، نہ اپنے بھائی کے بارے میں بغض و عداوت رکھنے والے کی، نہ اس کی جو ولاء اور قرابت میں متہم ہے اور نہ اس کی جو کسی گھر والوں کا خدمت گار (نوکر، غلام اور تابع) ہو۔‘‘","",{"k":"ضعيف: أخرجه الترمذى: 2298","e":"امام ترمذی رحمہ اللہ نے اس حدیث کو غریب قرار دیا ہے نیز یزید بن زیاد دمشقی راوی منکر الحدیث ہے۔ اس روایت میں بعض راویوں نے ان الفاظ کا اضافہ ذکر کیا ہے (وَلَا مَجْلُودٍ حَدًّا) ’’اور نہ اس کی گواہی جائز ہے جس پر حد لگی ہو۔‘‘"}],[2515,"جناب عمرو بن شعیب اپنے والد سے وہ (شعیب) اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ’’خائن مرد، خائن عورت اور اپنے بھائی کے ساتھ کینہ اور بغض رکھنے والے کی گواہی رد فرمائی ہے اور ایسے ہی جو کسی گھر والوں کا خدمت گار (نوکر، غلام اور تابع) ہو اس کی گواہی بھی قبول نہیں کی۔ البتہ دوسروں کے حق میں قبول ہے۔‘‘","",{"k":"حسن: أخرجه ابوداود: 3600، وابن ماجه: 2366","e":"امام بغوی رحمہ اللہ نے کہا: کسی شخص کی گواہی قبول کرنے کی سات شرائط ہیں: (۱) اسلام، (۲) آزادی، (۳) عقل و شعور، (۴) بلوغت، (۵) عدالت، (۶) مروّت اور (۷) ہر قسم کی تہمت سے پاک ہونا۔ اکثر اہل علم کے نزدیک ذمی (غیر مسلم شخص) کی گواہی مطلقاً کسی معاملے میں بھی قابل قبول نہیں۔ امام مالک اور شافعی رحمہما اللہ کا یہی قول ہے۔ امام شافعی رحمہ اللہ نے کہا: مسلمانوں میں سے بھی جو لوگ دروغ گوئی کی شہرت رکھتے ہوں ان کی گواہی قبول نہیں تو کافروں کی گواہی کیونکر قبول کی جاسکتی ہے جو اللہ عزوجل پر جھوٹ باندھے ہوئے ہیں۔ اہل رائے کا موقف ہے کہ ذمیوں کی گواہی آپس میں قبول کی جائے گی خواہ وہ مختلف دینوں کے حامل ہوں جبکہ بعض اہل علم کا موقف ہے کہ اگر ذمی ایک دین کے حامل ہوں تو ان کی آپس میں ایک دوسرے کے حق میں گواہی جائز ہے اور اگر وہ مختلف مذاہب کے پیروکار ہوں مثلاً یہودی، نصرانی یا مجوسی کے حق میں یا خلاف گواہی دے تو اسے قبول نہیں کیا جائے گا۔ امام شعبی، زہری، ابن ابی لیلیٰ، اور امام اسحاق رحمہم اللہ کا یہی موقف ہے۔ ان کی دلیل اللہ سبحانہ وتعالیٰ کا فرمان ہے:\n﴿ فَأَغْرَيْنَا بَيْنَهُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ ﴾ [سورہ مائدہ: ۱۴]\n’’تو ہم نے بھی ان کے آپس میں بغض و عداوت ڈال دی ہے۔‘‘\nاکثر اہل علم کا خیال ہے کہ اہل ذمہ کی گواہی مسلمانوں کے حق میں باطل ہے اسے قبول نہیں کیا جائے گا۔ اہل علم کی ایک جماعت کا خیال ہے کہ اگر کسی مسلمان کو ایسی جگہ موت کا سامنا ہو جہاں اس کی وصیت کے لیے مسلمان گواہ موجود نہ ہوں تو ان کی گواہی جائز ہے بالخصوص سفر وغیرہ میں۔ سیدنا ابو موسیٰ اشعری رضی اللہ عنہ سے اسی طرح مروی ہے۔ قاضی شریح، ابراہیم نخعی، اوزاعی اور امام احمد رحمہم اللہ اسی بات کے قائل ہیں۔ ان کی دلیل اللہ سبحانہ وتعالیٰ کا فرمان ہے:\n﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا شَهَادَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ حِينَ الْوَصِيَّةِ اثْنَانِ ذَوَا عَدْلٍ مِنْكُمْ أَوْ آخَرَانِ مِنْ غَيْرِكُمْ ﴾\n’’اے لوگو جو ایمان لائے ہو! جب تم میں کسی کو موت آنے لگے تو تمہارے درمیان گواہی ہونی چاہیے اور وصیت کے وقت اپنے (مسلمانوں) میں سے دو انصاف والے گواہ بنالو یا اگر تم زمین میں سفر پر نکلے ہو اور (راستے میں) موت کی مصیبت پیش آجائے تو غیر قوم کے دو گواہ بھی کافی ہوں گے۔‘‘\n[سورہ مائدہ: ۱۰۶] (صحیح بخاری: ۲۷۸۰) یعنی دو ایسے افراد جو تمہارے دین پر نہیں ہیں (یعنی غیر مسلم) جو علماء اہل ذمہ کی گواہی کے قائل نہیں وہ آیت کریمہ کے الفاظ ﴿أَوْ آخَرَانِ مِنْ غَيْرِكُمْ﴾.... کا یہ مطلب بیان کرتے ہیں کہ دو افراد جو موصی کے قبیلے کے علاوہ کسی اور قبیلے سے ہوں۔ اس کی وجہ یہ ہے کہ عام طور پر وصیت کرنے والا اپنے عزیز و اقارب اور قبیلے کے افراد کو ہی اپنی وصیت پر گواہ بناتا ہے اجنبیوں کو نہیں، ان حضرات نے اپنے معنی اور تاویل پر اللہ سبحانہ وتعالیٰ کے فرمان سے دلیل پکڑی ہے:\n﴿ إِنِ ارْتَبْتُمْ لَا نَشْتَرِي بِهِ ثَمَنًا وَلَوْ كَانَ ذَا قُرْبَى ﴾ [سورہ مائدہ: ۱۰۶]\n’’اگر تم کو شبہ ہو تو ان دونوں کو بعد نماز روک لو پھر دونوں اللہ کی قسم کھائیں کہ ہم اس قسم کے عوض کوئی نفع نہیں لینا چاہتے اگرچہ کوئی قرابت دار بھی ہو۔‘‘\nتو اللہ عزوجل کے الفاظ ﴿وَلَوْ كَانَ ذَا قُرْبَى﴾ اس بات پر دلالت کرتے ہیں کہ اسی آیت کریمہ میں مذکور لفظ ﴿مِنْكُمْ﴾ سے مراد موصی کے رشتہ دار اور قرابت دار بھی ہیں۔ اہل علم کی ایک جماعت کا خیال ہے کہ یہ آیت منسوخ ہے لیکن اکثر اہل علم کا موقف ہے کہ یہ آیت کریمہ منسوخ نہیں ہے۔ ام المومنین سیدہ عائشہ رضی اللہ عنہا، حسن بصری اور عمرو بن شرحبیل اسی موقف کے قائل ہیں ان حضرات کا کہنا ہے کہ سورۃ مائدہ قرآن مجید کی آخری آخری تنزیلات میں سے ہے اور اس کی کوئی آیت منسوخ نہیں ہے اور اس آیت کا سبب نزول وہی ہے جو سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ بنو سہم کا ایک شخص تمیم داری اور عدی بن بداء کی معیت میں سفر پر نکلا (دوران سفر) سہمی کی وفات ہوگئی جہاں کوئی مسلمان نہ تھا۔ جب وہ دونوں اس کا ترکہ لے کر آئے تو (وارثوں نے) چاندی کا ایک پیالہ گم پایا جس پر سونے کے پترے چڑھے ہوئے تھے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے دونوں سے قسم لی۔ پھر وہ جام مکہ میں مل گیا، (جن کے پاس سے ملا) انہوں نے کہا کہ ہم نے یہ تمیم داری اور عدی سے خریدا ہے۔ پھر مرنے والے سہمی کے وارثوں میں سے دو نے قسم کھائی اور کہا کہ ہماری گواہی ان کی گواہی سے زیادہ سچی ہے اور یہ جام ہمارے آدمی کا ہے۔ چنانچہ انہی کے سلسلے میں یہ آیت نازل ہوئی:\n﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا شَهَادَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ ﴾ [سورہ مائدہ: ۱۰۶]\n’’اے ایمان والو! تمہارے آپس میں دو شخص کا گواہ ہونا مناسب ہے جبکہ تم میں سے کسی کو موت آنے لگے۔‘‘\nبعض علماء نے اس آیت کا یہ مطلب بیان کیا ہے کہ اس میں غیر مسلموں کو وصی مقرر کرنے کا تذکرہ ہے گواہ بنانے کا نہیں۔ اس لیے کہ تمیم داری اور عدی بن بداء میت کی طرف سے وصی تھے گواہ نہ تھے اور اس فرق کی دلیل یہ ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ان دونوں سے قسم اٹھوائی جبکہ گواہوں سے قسم نہیں لی جاتی تو آیت مذکور کے لفظ ﴿شَهَادَةُ﴾ سے مراد وہ بار امانت ہے جو مرنے والے نے مرتے وقت ان دونوں کے سپرد کیا تھا۔ اسی طرح آیت کے الفاظ ﴿وَلَا نَكْتُمُ شَهَادَةَ اللَّهِ﴾ ’’اللہ تعالیٰ کی بات کو ہم پوشیدہ نہ کریں گے۔‘‘ (سورہ مائدہ: ۱۰۶) سے مراد بھی اللہ تعالیٰ کی امانت ہے۔ امام بغوی رحمہ اللہ نے کہا: شہادت اور گواہی کی قبولیت کے لیے آزادی شرط ہے اس لیے کہ گواہی کا تعلق حکومت و فرماں روائی اور بالا دستی کے معاملات سے ہے اور غلام ناقص ہوتا ہے۔ اہل علم کی ایک قوم کا خیال ہے کہ غلام کی گواہی قبول کی جائے گی ایسا موقف سیدنا انس رضی اللہ عنہ، قاضی شریح، زرارہ بن اوفی اور عثمان البتی سے منقول ہے۔ ابن سیرین نے کہا: غلام کی گواہی جائز تو ہے لیکن اگر اپنے مالک کے حق میں گواہی دے گا تو قبول نہیں کی جائے گی۔ حسن بصری اور ابراہیم نخعی نے کہا: معمولی اور کم حیثیت اشیاء کے متعلق غلام کی گواہی جائز ہے۔ مجنون اور دیوانے کی گواہی قبول نہیں کیونکہ اس کی بات کچھ معتبر نہیں نیز اس کی گواہی پر فیصلے ممکن نہیں۔ اسی طرح نابالغ کی گواہی بھی قابل قبول نہیں۔ اس کی دلیل اللہ سبحانہ وتعالیٰ کا فرمان ہے:\n﴿ وَاسْتَشْهِدُوا شَهِيدَيْنِ مِنْ رِجَالِكُمْ ﴾ [سورہ بقرہ: ۲۸۲]\n’’اور اپنے سے دو مرد گواہ رکھ لو۔‘‘\nامام مالک رحمہ اللہ کا کہنا ہے: بچوں کی گواہی زخموں وغیرہ میں قبول کی جائے گی لیکن شرط یہ ہے کہ وہ اپنی کھیل کود کی جگہ سے جہاں یہ واقعہ پیش آیا منتشر نہ ہوئے ہوں۔ اگر وہاں سے بکھر جائیں تو پھر ان کی گواہی قبول نہیں کی جائے گی۔ (بکھر جانے کی صورت میں کوئی بچوں کو غلط پٹی پڑھا سکتا ہے......) ابن زبیر رضی اللہ عنہ سے ایسا ہی مروی ہے۔ جناب شریح بچوں کی گواہی ایک دوسرے کے بارے میں جائز قرار دیتے ہیں۔ مروی ہے کہ سیدنا ابن عباس رضی اللہ عنہما بچوں کی گواہی کے جواز کے قائل نہیں تھے ان کی دلیل اللہ تعالیٰ کا یہ فرمان ہے:\n﴿ مِمَّنْ تَرْضَوْنَ مِنَ الشُّهَدَاءِ ﴾ [سورہ بقرہ: ۲۸۲]\n’’جنہیں تم گواہوں میں سے پسند کر لو۔‘‘\nیعنی جن کی دین داری اور عدالت پر تم مطمئن ہو اور شہادت کی قبولیت کے لیے عدالت شرط ہے (اور اس کا تعلق بالغ افراد کے ساتھ ہے بچوں اور نابالغ افراد کے ساتھ نہیں ہے) عدالت کی تعریف یہ ہے کہ وہ شخص کبیرہ گناہوں سے بچنے والا اور صغائر پر اصرار نہ کرنے والا ہو۔ خائن شخص کی گواہی مردود اور ناقابل تسلیم ہے جیسا کہ ایک حدیث میں مذکور ہے۔ امام شافعی رحمہ اللہ نے کہا: معاشرے میں ہم کسی ایسے شخص سے واقف نہیں جو سو فیصد اطاعت الہی اور صفت مروت رکھتا ہو اور معصیت کا ایک چھینٹا بھی اس کے کردار پر نہ پڑا ہو۔ اسی طرح کوئی معصیت کیش اور خلق مروّت سے بیگانہ شخص ایسا نہیں ہوتا جس کے دامن عصیاں میں کوئی نہ کوئی نیکی کا پھول نہ ہو بلکہ ضرور کوئی نیکی کا کنول اس کے دامن میں ہوتا ہے۔ بہر حال جب کسی شخص کے کردار میں نیکی اور تقویٰ نیز مروت کی کثرت ہوتو اس کی گواہی کو قبول کر لینا چاہیے اور جب کسی کے معاملے میں اغلب معصیت اور نافرمانی ہو نیز مروت کا فقدان ہو تو ایسے شخص کی شہادت کو مردود سمجھا جائے۔ سیدنا عمر بن خطاب رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں لوگوں کا وحی کے ذریعے سے مؤاخذہ ہو جاتا تھا۔ لیکن اب وحی کا سلسلہ ختم ہو گیا ہے اور ہم صرف انہیں امور میں مؤاخذہ کریں گے جو تمہارے عمل سے ہمارے سامنے ظاہر ہوں گے۔ اس لیے جو کوئی ظاہر میں ہمارے سامنے خیر کرے گا، ہم اسے امن دیں گے اور اپنے قریب رکھیں گے۔ اس کے باطن سے ہمیں کوئی سروکار نہ ہو گا۔ اس کا حساب تو اللہ تعالیٰ کرے گا اور جو کوئی ہمارے سامنے ظاہر میں برائی کرے گا تو ہم اسے امن نہیں دیں گے اور نہ ہم اس کی تصدیق کریں گے خواہ وہ یہی کہتا رہے کہ اس کا باطن اچھا ہے۔ (صحیح بخاری: ۲۶۴۱) امام بغوی رحمہ اللہ نے کہا: مروت، گواہی کی قبولیت کی بنیادی شرط ہے اور مروت سے مراد آداب عالیہ اور اخلاق فاضلہ ہیں جو ہر معاشرے میں معروف اور جانے پہچانے جاتے ہیں۔ ان سے محرومی قلت حیا کا باعث ہے۔ مروّت یہ ہے کہ آدمی کی وضع قطع اور لباس وغیرہ باوقار اور سنجیدگی لیے ہوئے ہو، اُس کا کردار وسیرت اجلا اور شفاف ہو، لوگوں کے ساتھ اس کا میل جول شگفتہ اور شاداب ہو، اس کے معاملات نکھرے ہوئے اور شرعی تعلیمات کے آئینہ دار ہوں۔ اس کے برعکس اگر کسی شخص سے ایسے آداب و اخلاق کا صدور ہو جن کا اظہار عموماً اچھا نہیں سمجھا جاتا بلکہ باعث ننگ و عار تصور کیا جاتا ہے تو ایسے شخص کی گواہی کو رد کر دیا جائے گا خواہ وہ امور جن میں وہ ملوث ہے فی نفسہ مباح ہی کیوں نہ ہوں۔ امام بغوی رحمہ اللہ نے کہا: گواہی کے جائز ہونے کے لیے گواہ کی شخصیت کا تہمت اور الزام سے بری ہونا ضروری ہے۔ اسی اصول کو مدنظر رکھتے ہوئے دشمن کی دشمن کے حق میں گواہی قبول نہیں اگر چہ اس کی گواہی دوسروں کے حق میں قبول ہے، دشمن کے حق میں اس کی گواہی کے قبول نہ ہونے کی وجہ یہ ہے کہ دشمن کے حق میں اس کی شخصیت متہم ہے اور اس بات کا قوی اندیشہ ہے کہ وہ جھوٹی گواہی دے کر اسے بھاری نقصان پہنچا دے اگر کوئی شخص کسی کی دشمنی میں فسق و فجور کی حدوں کو نہیں چھوتا بلکہ اعتدال میں رہتا ہے تو اس کی گواہی قبول کی جاسکتی ہے اور اگر کوئی شخص دشمنی میں انتہا تک پہنچ جاتا ہے اور فسق و فجور کا برملا اظہار کرنے سے نہیں چوکتا تو ایسے شخص کی گواہی بالعموم مردود ہے۔ امام ابو حنیفہ رحمہ اللہ اس بات کے قائل ہیں کہ دشمن کی گواہی قبول کی جائے گی بشرطیکہ وہ عادل ہو۔ جو علمائے کرام دشمن کی گواہی کے قبولیت کے قائل نہیں یہ حدیث مبارکہ ان کی دلیل ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے اپنے ایک فرمان میں اپنے بھائی کے خلاف کینہ اور بغض رکھنے والے شخص کی گواہی کو مردود قرار دیا ہے۔ ذُو الْغِمْرِ: کینہ پرور شخص، اس کے اور مشہود لہ (جس کے حق میں گواہی دی جارہی ہے) کے درمیان واضح دشمنی اور نفرت ہو۔ الغمر کا معنی بغض و عداوت ہے۔ سیدنا عمر رضی اللہ عنہ سے مروی ہے کہ جو لوگ کسی شخص کے بارے میں ایسی گواہی دیں جس کے نتیجے میں حد واجب ہوتی ہو اور انہوں نے بچشم خود اسے کام میں ملوث نہ دیکھا ہو (بلکہ بغیر دیکھے گواہی جڑ دی ہو) تو ایسے لوگوں نے کینے اور بغض کی بنا پر گواہی دی ہے۔ (وَلَا ظَنِينٍ فِي وَلَاءٍ وَلَا قَرَابَةٍ) ’’نہ اس کی جو ولاء اور قرابت میں متہم ہے۔‘‘ اس سے مراد وہ شخص ہے جس نے اپنا نسب بدل لیا ہو اور اس پر تہمت ہو کہ وہ اپنے باپ کو چھوڑ کر کسی دوسرے شخص کی جانب اپنی نسبت کرنے لگا ہے۔ اسی طرح وہ آزاد شدہ غلام جو اپنے آقاؤں کے بجائے کسی اور کی طرف منسوب ہونے لگے یہ لفظ اللہ سبحانہ وتعالیٰ کے فرمان میں مستعمل ہے:\n﴿ وَمَا هُوَ عَلَى الْغَيْبِ بِظَنِينٍ ﴾ [التکویر: ۲۴]\n’’اور یہ غیب کی باتوں کو بتلانے میں بخیل نہیں۔‘‘\nیعنی ہمارے نبی پر یہ اتہام نہیں کہ انہیں جن باتوں کی اطلاع دی جاتی ہے اور جو دین ان پر نازل ہوتا ہے وہ اس میں سے کوئی بات اپنے پاس رکھ لیتے ہیں۔ جو شخص اپنے والد یا اولاد کے حق میں گواہی دے اسے متہم ہی تصور کیا جائے گا اور اس کی گواہی ان رشتوں کے متعلق قبول نہیں کی جائے گی۔ ابن سیرین رحمہ اللہ نے کہا: (لَمْ يَكُنْ عَلِيٌّ يُظَنُّ فِي قَتْلِ عُثْمَانَ) کے جملے کا معنی ہے کہ سیدنا عثمان رضی اللہ عنہ کے قتل کا کوئی اتہام سیدنا علی رضی اللہ عنہ کی ذات پر نہیں ہے۔ ایسا شخص جو اپنے دین کے معاملے میں متہم ہو اس کی گواہی بھی مردود ہے۔ (وَرَدَّ شَهَادَةَ الْقَانِعِ لِأَهْلِ الْبَيْتِ) ’’اور آپ نے ایسے شخص کی گواہی کو رد فرما دیا جو کسی گھر میں پلتا ہے۔‘‘ القانع سے مراد تابع رہنے والا ہے جیسے کہ کوئی خاص نوکر ہوتا ہے۔ لفظ القنوع کے لغوی معنی سوال کرنے کے ہیں اور القانع سوال کنندہ کو کہتے ہیں۔ جب کوئی شخص کسی سے کوئی چیز مانگے تو اس کو قنع، یقنع، قنوعا کے الفاظ سے بیان کیا جاتا ہے۔ حدیث مبارکہ میں مذکور لفظ القانع سے مراد ایسا شخص ہے جو کسی گھرانے کا خدمت گار ہو اور ان کے کام کاج کر دیتا ہو جیسے نوکر، غلام اور شاگرد پیشہ ور لوگ ہوتے ہیں، ان کا نفع اس کا نفع ہے اور ان کا نقصان دراصل اس کا زیاں ہے، اس لیے جب ایسا شخص اپنے مالکوں اور آقاؤں کے حق میں گواہی دے گا تو بہت ممکن ہے اپنے منافع کو سامنے رکھتے ہوئے اس کے قدم ڈگمگا جائیں کیونکہ ان کا فائدہ دراصل اس کا اپنا فائدہ ہے۔ اس لیے ایسے شخص کی گواہی بھی قابل قبول نہیں۔ جیسے کوئی شخص ایسے گھر کے خریدنے کے متعلق کسی شخص کے حق میں گواہی دے جس گھر میں وہ شفعہ کر سکتا ہو، یا کوئی شخص جو مفلس اور دیوالیہ ہو چکا ہو اس کے قرض خواہوں میں سے کوئی ایک اس بات کی گواہی دے کہ اس مفلس نے فلاں سے قرض لینا ہے (وہ لے کر ہم میں بانٹ دیا جائے) تو ایسے شخص کی گواہی بھی قبول نہیں یا کوئی شخص کسی کے خلاف گواہی دے کہ اس نے میرے مورث کو قتل کیا ہے (تا کہ وہ قاتل ہونے کی بنا پر وراثت سے محروم قرار پائے اور میرا حصہ وراثت میں بڑھ جائے) ایسے شخص کی گواہی بھی قبول نہیں کیونکہ ان صورتوں میں گواہی دینے کا فائدہ گواہ کو پہنچتا ہے۔ اسی اصول پر قیاس کرتے ہوئے کہا جائے گا کہ خاوند کی گواہی بیوی کے حق میں اور بیوی کی خاوند کے حق میں قبول نہیں۔ یہ امام ابو حنیفہ رحمہ اللہ کا قول ہے جبکہ کچھ دوسرے علماء اس صورت میں جواز کے قائل ہیں۔ امام شافعی رحمہ اللہ کا بھی یہی قول ہے۔ اکثر اہل علم کے نزدیک والد کی گواہی اولاد کے حق میں اور اولاد کی گواہی والد کے حق میں جائز نہیں۔ البتہ ان کی گواہی خلاف میں قبول ہے۔ بعض اہل علم یہ موقف بھی رکھتے ہیں کہ والد کی گواہی اولاد کے حق میں اور اسی طرح اولاد کی گواہی والد کے حق میں قبول کی جائے گی، قاضی شریح، داود ظاہری اور امام ثور کا یہ قول ہے۔ تمام اہل علم کا اس بات پر اتفاق ہے کہ بھائی کی گواہی بھائی کے حق میں اور اسی طرح رشتہ داروں کی آپس میں گواہی قبول کی جائے گی۔ اکثر اہل علم کا موقف ہے کہ دیہاتی کی گواہی قبول کی جائے گی بشرطیکہ وہ عادل اور ثقہ ہو۔ امام مالک رحمہ اللہ نے کہا: شہری کے خلاف دیہاتی کی گواہی قبول نہیں کی جائے گی اور وہ اس بارے میں ایک حدیث بھی روایت کرتے ہیں کہ سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ’’کسی دیہاتی کی شہری کے خلاف گواہی جائز نہیں۔‘‘ جواز کے قائل حضرات اس حدیث مبارکہ کا یہ مطلب بیان کرتے ہیں کہ اگرچہ یہ بات اپنی جگہ درست ہے کہ بدوی عموماً مستقل آبادیوں کے حالات، عادات، رسم و رواج اور طور طریقوں سے واقف نہیں ہوتے، بڑے سادہ لوح ہوتے ہیں، اس لیے مشاہدے میں انہیں غلطی لگنے یا عدم فہم کا امکان زیادہ ہوتا ہے نیز وہ احکام شریعت سے بھی نابلد ہوتے ہیں اس لیے ان کی گواہی قبول نہیں کی جاسکتی مگر جو دیہاتی سمجھ دار، معاملہ فہم، زیرک اور عادل و ثقہ ہو اس کی اور ایک شہری شخص کی گواہی میں کوئی فرق نہیں، یعنی وہ معاملات جن کا فہم اہل بادیہ کے لیے آسان ہے اس میں ان کی گواہی ہر طرح معتبر ہے۔ نابینا شخص کی گواہی ان امور میں معتبر ہے جن کا تعلق سماعت سے ہے یا ایسا موقع ہو جہاں نابینا کی گواہی پر شک و شبہ کی کوئی گنجائش نہ ہو، مثلاً ایک شخص نے نابینا آدمی کے کان میں کسی دوسرے شخص کے متعلق کسی بات کا اقرار کیا، اس نے اس کو وہیں دبوچ لیا اور اس کے خلاف گواہی دے ڈالی (تو نابینا شخص کی گواہی معتبر ہوگی) جناب قاسم، حسن بصری، ابن سیرین، زہری، حکم، عطاء اور شعبی رحمہم اللہ اندھے کی گواہی کے جائز ہونے کے قائل ہیں۔ امام زہری رحمہ اللہ نے کہا: اچھا بتاؤ اگر ابن عباس رضی اللہ عنہ کسی معاملے میں گواہی دیں تو تم اسے رد کر سکتے ہو۔ اور بعض علماء نے کہا: اندھا شخص جب آواز پہچان جائے تو اس کی گواہی جائز ہے۔ بعض الناس (حنفیہ) نے کہا: اندھے کی گواہی کسی حال میں بھی معتبر اور جائز نہیں۔ احناف نے نابینا شخص کی گواہی کو فوت شدہ اور غائب شخص کے لیے جائز قرار دیا ہے۔ اہل رائے کا بھی یہی قول ہے، سیدنا سمرہ بن جندب رضی اللہ عنہ نے نقاب پوش عورت کی گواہی جائز قرار دی تھی۔ اور قاذف (تہمت لگانے والا) شخص کی گواہی قبول نہیں کی جائے گی بلکہ وہ مردود الشہادہ قرار پائے گا اور اگر وہ توبہ کرلے اور اس کے بعد اس کی حالت درست ہو جائے اور سیرت و کردار نکھر جائے تو اس کی گواہی قبول کی جائے گی خواہ اس نے توبہ حد لگنے سے پہلے کی ہو یا بعد میں۔ اس کی دلیل اللہ سبحانہ وتعالیٰ کا فرمان ہے:\n﴿ وَلَا تَقْبَلُوا لَهُمْ شَهَادَةً أَبَدًا وَأُولَئِكَ هُمُ الْفَاسِقُونَ إِلَّا الَّذِينَ تَابُوا مِنْ بَعْدِ ذَلِكَ وَأَصْلَحُوا ﴾ [النور: ۴، ۵]\n’’اور کبھی ان کی گواہی قبول نہ کرو۔ یہ فاسق لوگ ہیں ہاں جو لوگ اس کے بعد توبہ اور اصلاح کر لیں۔‘‘\nاکثر اہل علم کا یہی قول ہے (کہ توبہ کے بعد وہ فاسق نہیں رہے گا اور مقبول الشہادہ ہو جائے گا۔) جناب سعید بن مسیب رحمہ اللہ سے مروی ہے کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے جب ان تین اشخاص کو حد لگائی جنہوں نے سیدنا مغیرہ بن شعبہ رضی اللہ عنہ کے خلاف گواہی دی (اور تہمت لگائی تھی) پھر ان سے توبہ کرنے کا کہا: تو دو (شبل بن معبد اور نافع) نے توبہ کر لی تو ان کی گواہی قبول کی اور ابو بکرہ نے توبہ کرنے سے انکار کر دیا تو اس کی گواہی رد کر دی گئی۔ اور مروی ہے کہ سیدنا عمر رضی اللہ عنہ نے ابو بکرہ سے کہا تھا: توبہ کر لے، تیری گواہی قبول کی جائے گی یا یہ کہا کہ اگر تو توبہ کر لے گا تو میں تیری گواہی قبول کروں گا۔ سیدنا ابن عباس رضی اللہ عنہ کا یہی قول ہے۔ جناب عطاء، طاؤس، مجاہد، سعید بن جبیر، سلیمان بن یسار، عکرمہ، عبداللہ بن عقبہ، عمر بن عبدالعزیز اور زہری رحمہم اللہ کا یہی موقف ہے۔ امام مالک، شافعی رحمہما اللہ کا بھی یہی مذہب ہے۔ امام شعبی رحمہ اللہ نے کہا: اللہ تعالیٰ تو اس کی توبہ قبول کرتا ہے اور تم اس کی گواہی قبول نہیں کرتے؟ امام نخعی رحمہ اللہ نے کہا: اس کی گواہی قبول نہیں کی جائے گی۔ اہل رائے کا موقف ہے کہ اس کی گواہی مجرد الزام تراشی اور قذف سے مردود نہیں ٹھہرے گی البتہ جب اسے حد لگا دی جائے گی تو اس کی گواہی ہمیشہ ہمیشہ کے لیے مردود قرار پائے گی اور توبہ کے بعد بھی اس کی گواہی قبول نہیں کی جائے گی۔ پھر ان کا موقف ہے کہ مجلود (جسے حد میں کوڑے لگائے گئے ہوں) کی گواہی سے نکاح منعقد ہو جائے گا اور اگر اسے منصب قضا سونپ دیا جائے تو اس کے فیصلوں کو صحیح اور نافذ سمجھا جائے گا۔ امام شافعی رحمہ اللہ نے ان کے اس موقف پر نقد کرتے ہوئے کہا: مجلود شخص حد لگنے سے پہلے بدترین حالت میں ہوتا ہے اور حد لگائے جانے کے بعد بہتر حالت میں آجاتا ہے اس لیے کہ حدود کفارات ہیں، ان کے لگنے سے گناہ جھڑتے اور سیئات ختم ہوتی ہیں۔ عجیب بات ہے کہ جب وہ بہتر حالت میں ہوتا ہے تب تم اس کی گواہی قبول کر لیتے ہو؟ جب تم کافر اور جان بوجھ کر قتل کرنے والے کی توبہ کو قبول کر لیتے ہو تو قاذف (تہمت لگانے والے) کی توبہ کو کیوں قبول نہیں کرتے حالانکہ اس کا گناہ ہلکا ہے۔","f":"رجال کی تعریف میں کم عقل، بچہ یا مجنون نہیں آتے بلکہ عقل و شعور سے متصف بالغ افراد آتے ہیں۔ (ع، س) ایک روایت میں یہ الفاظ ہیں (لَا تَجُوزُ شَهَادَةُ خَائِنٍ وَلَا خَائِنَةٍ) ’’خائن مرد اور خائن عورت کی گواہی جائز نہیں۔‘‘ (صحیح ابوداود: ۳۰۶۸) اس لیے کہ خائن شخص فاسق ہوتا ہے اور خیانت کے ارتکاب سے اس کی عدالت مجروح ہو جاتی ہے۔ ابوعبید نے کہا: ہمارا خیال ہے کہ لفظ خیانت کو صرف مالی معاملات تک محدود نہ رکھا جائے جس کا تعلق لوگوں کے ساتھ لین دین میں ہوتا ہے بلکہ اس میں فرائض کو بھی شامل سمجھا جائے۔ جو شخص اوامر شریعت کو پامال کرنے والا اور نواہی کا ارتکاب کرنے والا ہو وہ بھی عادل نہیں ہوسکتا۔ اس کی گواہی بھی قابل قبول نہیں۔ اس لیے اس پر بدرجہ اولیٰ لفظ خیانت صادق آتا ہے۔ توبہ سے کوڑوں کی سزا تو معاف نہیں ہوگی، وہ تائب ہو جائے یا اصرار کرے، یہ سزا تو بہر حال ملے گی۔ البتہ دوسری دو باتیں جو ہیں، مردود الشہادہ اور فاسق ہونا، اس کے بارے میں اختلاف ہے، بعض علماء اس استثنا کو فسق تک محدود رکھتے ہیں یعنی توبہ کے بعد وہ فاسق نہیں رہے گا اور بعض مفسرین دونوں جملوں کو اس میں شامل سمجھتے ہیں، یعنی توبہ کے بعد مقبول الشہادہ بھی ہو جائے گا۔ امام شوکانی رحمہ اللہ نے اسی دوسری رائے کو ترجیح دی ہے اور ابداً کا مطلب بیان کیا ہے: ’’مادام قاذفًا‘‘ یعنی جب تک وہ بہتان تراشی پر قائم رہے، جس طرح کہا جائے کہ کافر کی شہادت کبھی قبول نہیں، تو یہاں ’’کبھی‘‘ کا مطلب یہی ہوگا کہ جب تک وہ کافر ہے۔ مزید برآں کفر قذف سے بڑا جرم ہے۔ جب کافر کی توبہ قبول ہے تو قاذف کی کیوں نہیں؟ بہر حال جمہور کا موقف راجح ہے۔ (ع، س) (قیاس کے دعویداروں کی یہ عجیب منطق ہماری سمجھ سے بالاتر ہے بلکہ عقل اور قیاس کے تقاضوں کے بھی سراسر خلاف ہے۔ امام شافعی رحمہ اللہ کی گرفت حد درجہ مضبوط اور کاری ہے......)۔ (ع، س)"}],[2516,"سیدنا عبداللہ بن عامر رضی اللہ عنہ سے منقول ہے کہ سیدنا عمر رضی اللہ عنہ کے پاس ایک جھوٹے گواہ کو لایا گیا۔ آپ نے اسے ایک روز صبح سے رات تک لوگوں کے لیے کھڑا کیے رکھا اور آپ کہتے: یہ فلاں شخص ہے اور اس نے جھوٹی گواہی دی ہے۔ اس کو اچھی طرح پہچان لو، پھر اسے قید کر دیا۔","",{"k":"ضعيف: أخرجه البيهقى: 10 / 141، وعبد الرزاق في المصنف: 15388","e":"اور گواہ کو چاہیے کہ وہ علم و بصیرت کی بنیاد پر گواہی دے۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے:\n﴿ إِلَّا مَنْ شَهِدَ بِالْحَقِّ وَهُمْ يَعْلَمُونَ ﴾ [الزخرف: ۸۶]\n’’ہاں (مستحق شفاعت وہ ہیں) جو حق بات کا اقرار کریں اور انہیں علم بھی ہو۔‘‘\nنیز اللہ جل ذکرہ کا فرمان ہے:\n﴿ وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ ﴾ [الاسراء: ۳۶]\n’’جس بات کی تجھے خبر ہی نہ ہو اس کے پیچھے مت پڑ۔‘‘\nیعنی جس چیز کا علم نہیں، اس کے پیچھے مت لگو۔ بعض گواہیاں ایسی ہیں جن میں گواہ کی رؤیت اور بصارت شرط ہے مثلاً قتل کی گواہی یا کسی کے نقصان ہو جانے کی گواہی۔ بعض گواہیوں کا تعلق محض سماعت سے ہے، ان میں صرف سن لینا کافی ہے مثلاً، نسب اور فلاں قوم قبیلے سے ہونا اور عمومی جائیدادیں اور املاک وغیرہ۔ بعض گواہیاں ایسی ہیں جن میں سماعت اور معاینہ دونوں کا ہونا ضروری ہے، مثلاً خرید و فروخت اور کسی بات یا معاہدے وغیرہ کا اقرار کرنا۔ ان میں معاہدے کے فریقین (عقد کرنے والے اور اقرار کنندہ) کے اقرار کے وقت موجود ہونا اور دونوں کے بول سننا ضروری ہے (یعنی معاینہ اور سماع شرط ہے) علمائے کرام کا اس بارے میں اختلاف ہے کہ آیا آزادی، ولاء (آزادی کی نسبت) نکاح اور وقف وغیرہ میں صرف سماع کافی ہے یا نہیں؟ بعض علماء نے ان تمام امور میں مجرد سماع کو کافی جانا ہے۔ جیسے نسب کا معاملہ ہے اور بعض عمومی سماعت کو کافی نہیں سمجھتے بلکہ صاحب معاملہ سے بالمشافہ سننا ضروری قرار دیتے ہیں۔ امام زہری رحمہ اللہ نے پردے کے پیچھے سے کسی خاتون کے متعلق گواہی دینے کے بارے میں کہا: اگر تو اس عورت کو پہچانتا ہے (آواز وغیرہ سے) تو گواہی دے ڈال وگرنہ، نہ دے۔ علمائے کرام نے چھپے ہوئے شخص کی گواہی کو درست اور جائز قرار دیا ہے۔ سیدنا عمرو بن حریث رضی اللہ عنہ نے کہا کہ جھوٹے بے ایمان شخص کے ساتھ ایسی صورت اختیار کی جاسکتی ہے۔ اور جناب حسن بصری رحمہ اللہ نے کہا: اسے اس طرح کہنا چاہیے کہ اگرچہ ان لوگوں نے مجھے گواہ نہیں بنایا لیکن میں نے اس اس طرح سنا ہے۔ جب کوئی شخص کسی غائب اور غیر موجود شخص کے بارے میں اپنے کسی حق کا دعویٰ دائر کر کے قاضی کے حضور دلیل پیش کر دے، قاضی اس حجت اور دلیل کو سن کر فریاد کنندہ کے حق میں فیصلہ صادر کر کے فریق ثانی کے شہر کے قاضی کو لکھ بھیجے اور اسے اپنے فیصلے پر گواہ بنالے تو اس کیفیت کو بعض اہل علم نے جائز قرار دیا ہے۔ امام مالک اور امام شافعی رحمہما اللہ کا یہی قول ہے۔ بعض اہل علم نے ایسی صورت میں غائب اور غیر حاضر شخص کے بارے میں گواہی سننے کو تو جائز قرار دیا ہے لیکن اس گواہی کی بنیاد پر فیصلہ کر دینے کو جائز نہیں سمجھا بلکہ اس کیفیت میں فریق ثانی کے شہر کے قاضی کو تحریر کیا جائے گا کہ جھگڑے کی نوعیت کا گہرا جائزہ لیتے ہوئے فیصلہ صادر کیا جائے، اہل رائے کا موقف یہی ہے۔ البتہ اگر حقیقت حال کا جائزہ لینے کے بعد واضح ہو جائے کہ جھگڑے کا فیصلہ وہی بنتا ہے جو پچھلے قاضی نے کیا ہے تو پھر اس کے فیصلے کو لاگو کر دیا جائے گا اور اس کیفیت کو اہل رائے نے بھی جائز قرار دیا ہے۔ بعض لوگوں نے کہا: حاکم جو پروانے اپنے نائبوں کو لکھے ان پر عمل ہو سکتا ہے۔ مگر حدود شرعیہ میں نہیں ہوسکتا (کیونکہ ڈر ہے کہ پروانہ جعلی نہ ہو)۔ اور ابراہیم نخعی رحمہ اللہ نے کہا: ایک قاضی دوسرے قاضی کے خط پر عمل کر لے جب اس کی مہر اور خط کو پہچانتا ہو تو یہ جائز ہے۔ اور امام شعبی رحمہ اللہ مہر لگے خط کو جو ایک قاضی کی طرف سے آئے جائز رکھتے تھے۔ اور سیدنا عبداللہ بن عمر رضی اللہ عنہما سے بھی ایسا ہی منقول ہے۔ اور ایاس بن معاویہ (بصرہ کے قاضی)، حسن بصری، ثمامہ بن عبداللہ بن انس، بلال بن ابی بردہ (بصرہ کے قاضی)، عبداللہ بن بریدہ اسلمی (مرو کے قاضی) اور عباد بن منصور (بصرہ کے قاضی) یہ سب لوگ ایک قاضی کا خط دوسرے قاضی کے نام بغیر گواہوں کے منظور کرتے۔ اگر فریق ثانی جس کو اس خط سے ضرر ہوتا ہے وہ یوں کہے کہ یہ خط جعلی ہے تو اس کو حکم دیں گے کہ اس کا ثبوت دے اور قاضی کے خط پر سب سے پہلے ابن ابی لیلیٰ (کوفہ کے قاضی) اور سوار بن عبداللہ (بصرہ کے قاضی) نے گواہی کا مطالبہ کیا۔ شہادت اور گواہی کی قبولیت کے لیے گواہوں کا متعدد ہونا شرط ہے حتی کہ کسی جھگڑے کا فیصلہ ایک گواہ سے نہیں ہو سکتا۔ اسی طرح ایک شخص کا تزکیہ کافی نہیں بلکہ اس میں بھی دو شخصوں کا تزکیہ ہونا ضروری ہے۔ بعض علماء نے ایک شخص کے تزکیہ کو کافی سمجھا ہے، ابو جمیلہ نے کہا: میں نے ایک لڑکا راستے میں گرا ہوا پایا، سیدنا عمر رضی اللہ عنہ نے مجھ پر اس بارے میں بدگمانی کی تو میرے قبیلے کے سردار نے کہا: یہ صالح آدمی ہے۔ سیدنا عمر رضی اللہ عنہ نے کہا کہ ایسی بات ہے تو پھر اس بچے کو لے جا، اس کا نفقہ ہمارے (بیت المال کے) ذمے رہے گا۔ ایک قیافہ شناس کی گواہی کافی ہے جس طرح ایک قاضی کا فیصلہ کر دینا کافی ہوتا ہے، اگر قاضی فریقین یا ایک فریق کی زبان نہ سمجھتا ہو تو کیا ایک ترجمان کافی ہے؟ اس بارے میں اہل علم کے درمیان اختلاف پایا جاتا ہے۔ بعض اہل علم کا خیال ہے کہ دو ترجمہ کرنے والوں کا ہونا ضروری ہے جس طرح دو گواہوں اور دو تزکیہ دینے والوں کا ہونا ضروری ہے۔ امام شافعی رحمہ اللہ کا یہی قول ہے۔ اہل علم کی ایک جماعت کا موقف ہے کہ ایک مترجم کا ہونا کافی ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے سیدنا زید بن ثابت رضی اللہ عنہ کو یہودیوں کی تحریر سیکھنے کا حکم فرمایا تھا تو (آپ کی طرف سے) وہی انہیں (خطوط) لکھتے تھے اور ان کے خطوط آپ کو پڑھ کر سناتے تھے۔ (حسن صحیح، ابوداود: ۳۶۴۵، ترمذی: ۲۷۱۵) سیدنا عمر رضی اللہ عنہ نے عبدالرحمن بن حاطب سے پوچھا، اس وقت ان کے پاس علی، عبدالرحمن اور عثمان رضی اللہ عنہم بھی موجود تھے کہ یہ لونڈی کیا کہتی ہے؟ عبدالرحمن بن حاطب نے کہا کہ امیر المومنین یہ آپ کو اس کے متعلق بتاتی ہے جس نے اس کے ساتھ زنا کیا (یعنی ایک ترجمہ کرنے والے کو کافی سمجھا گیا) اور ابو جمرہ نے کہا کہ میں ابن عباس رضی اللہ عنہ اور لوگوں کے درمیان ترجمانی کرتا تھا۔ امام شافعی رحمہ اللہ کے اقوال اور فصلوں اور پھلوں کا اندازہ لگانے والے اور مال غنیمت اور زکاۃ وغیرہ تقسیم کرنے والے کے متعلق مختلف ہیں کہ کیا ان میں بھی دو افراد کا ہونا ضروری ہے یا نہیں۔ اسی طرح اگر قاضی کے کانوں میں ثقل ہو یعنی اونچا سنتا ہو تو کیا اس کو سنانے کے لیے ایک شخص کافی ہے۔ اس بارے میں بھی امام شافعی رحمہ اللہ کے شاگردوں کے مابین اختلاف رائے پایا جاتا ہے۔","f":"یعنی جو جھوٹا بے ایمان آدمی ہو اور لوگوں کے روبرو کسی کا حق تسلیم کرنے سے ڈرتا ہے ایسا نہ ہو کہ وہ لوگ اس پر گواہ بن جائیں اور تنہائی میں اقرار کرتا ہے تو اس کا اقرار چھپ کر سن سکتے ہیں۔ (ع، س)"}],[2517,"سیدنا زید بن خالد جہنی رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا میں تمہیں بہترین گواہ نہ بتاؤں؟ وہ جو طلب کرنے سے پہلے از خود اپنی گواہی پیش کر دے۔‘‘","",{"k":"أخرجه مسلم: 1719","e":"امام بغوی رحمہ اللہ نے کہا: باسند صحیح سیدنا عمران بن حصین رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «خَيْرُ النَّاسِ قَرْنِي، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ» قَالَ عِمْرَانُ: فَلَا أَدْرِي أَقَالَ بَعْدَ قَرْنِهِ مَرَّتَيْنِ أَوْ ثَلَاثًا، «ثُمَّ يَكُونُ بَعْدَهُمْ قَوْمٌ يَشْهَدُونَ، وَلَا يُسْتَشْهَدُونَ، وَيَحْلِفُونَ، وَلَا يُسْتَحْلَفُونَ»...... ’’میرے زمانے کے لوگ سب سے بہترین ہیں، پھر وہ لوگ جو ان کے بعد ہوں گے، پھر وہ لوگ جو ان کے بعد ہوں گے۔‘‘ سیدنا عمران رضی اللہ عنہ نے کہا: ’’مجھے معلوم نہیں آپ نے اپنے زمانے کے بعد دو مرتبہ کہا یا تین مرتبہ (یعنی دو زمانوں کا ذکر کیا یا تین کا) پھر اس کے بعد کچھ لوگ ایسے آئیں گے جو گواہیاں دیں گے حالانکہ ان سے گواہی طلب نہیں کی جائے گی۔ اور قسم کھائیں گے حالانکہ ان سے قسم طلب نہیں کی جائے گی۔‘‘ (صحیح بخاری: ۲۶۵۱، صحیح مسلم: ۲۵۳۵) امام بغوی رحمہ اللہ نے کہا: جب کوئی شخص دوسرے آدمی پر اپنے حق کا دعویٰ کر دے اور کوئی شخص حاکم کے مطالبہ گواہی سے قبل ہی از خود گواہی دے ڈالے تو ایسی گواہی کی کوئی اہمیت نہیں۔ حاکم کو چاہیے کہ اس قسم کی گواہی سے فیصلہ نہ کرے۔ جس طرح اس قسم کی کوئی وقعت نہیں جو کسی کا حق غصب کرنے کیلئے اٹھائی جائے اور حاکم کے قسم اٹھوانے سے پہلے ہی اٹھائی جائے۔ باب کی ان دونوں حدیثوں کے مابین تطبیق کیسے دی جائے کہ ایک حدیث میں از خود گواہی دینے والے کو بہتر گواہ قرار دیا گیا ہے اور دوسری میں اسے قیامت کی علامت اور نشانی قرار دیا گیا ہے۔ اس بارے میں علماء کے مابین خاصا اختلاف پایا جاتا ہے۔ ایک قول کے مطابق (بِخَيْرِ الشُّهَدَاءِ) ’’بہترین گواہ‘‘ سے مراد یہ ہے کہ صاحب حق کو علم نہ ہو کہ اس کا گواہ کون ہے اور وہ گواہ از خود اپنے آپ کو سلطان کے روبرو پیش کر دے اور اس کے حق میں گواہی دے اور گواہی نہ چھپائے اور (يَشْهَدُونَ وَلَا يُسْتَشْهَدُونَ) ’’جو گواہیاں دیں گے حالانکہ ان سے گواہی طلب نہیں کی جائے گی‘‘ کا مطلب ہے کہ جب صاحب حق کو معلوم ہو کہ فلاں شخص میرا گواہ ہے اور گواہ بغیر گواہی طلب کیے آگے بڑھ بڑھ کر گواہیاں دے۔ یہ بھی کہا گیا ہے کہ بہترین گواہ کا تعلق اس امانت اور عاریت سے ہے جو کسی یتیم کی ہو اور سوائے اس گواہ کے کسی اور کے علم میں نہ ہو اور وہ از خود حاکم کے پاس جا کر حقدار کا حق دلوا دے تو یقیناً وہ بہترین گواہ ہو گا۔ یہ بھی کہا گیا ہے کہ خیر الشہداء سے مراد وہ گواہ ہے جو پہلی مرتبہ ہی بندے سے بغیر پس و پیش کیے گواہی کے لیے چلا آئے اور تنگ نہ کرے۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے:\n﴿ وَلَا يَأْبَ الشُّهَدَاءُ إِذَا مَا دُعُوا ﴾ [سورہ بقرہ: ۲۸۲]\n’’اور گواہوں کو چاہیے کہ وہ جب بلائے جائیں تو انکار نہ کریں۔‘‘\nجناب سعید بن جبیر رحمہ اللہ نے کہا: اس سے مراد گواہ ہے کہ وہ شہادت کی ادائیگی سے خواہ مخواہ انکار نہ کرے، ہر وہ شخص جو کسی واقعے یا معاملے کا گواہ ہو اسے جب گواہی دینے کے لیے بلایا جائے اور اس کے پاس پیچھے رہنے کا کوئی معقول اور شرعی عذر نہ ہو تو بحیثیت مسلمان اس پر سلطان کے رو برو آ کر گواہی دینا واجب ہے۔ اللہ سبحانہ وتعالیٰ کا فرمان ہے:\n﴿ وَلَا تَكْتُمُوا الشَّهَادَةَ وَمَنْ يَكْتُمْهَا فَإِنَّهُ آثِمٌ قَلْبُهُ ﴾ [سورہ بقرہ: ۲۸۳]\n’’اور گواہی کو نہ چھپاؤ اور جو اسے چھپالے وہ گنہ گار دل والا ہے۔‘‘\nاور اللہ عزوجل کے فرمان:\n﴿ فَلَا تَتَّبِعُوا الْهَوَى أَنْ تَعْدِلُوا ﴾ [سورہ نساء: ۱۳۵]\n’’تم خواہش نفس کے پیچھے پڑ کر انصاف نہ چھوڑ دینا۔‘‘\nیعنی خواہش نفس، عصبیت یا بغض تمہیں انصاف کرنے اور صحیح صحیح حق پر مبنی گواہی دینے سے نہ روک دے۔ یہ بھی کہا گیا ہے کہ اس جملے کا معنی ہے: تم خواہش نفس کے پیچھے نہ لگنا تا کہ تم عدل و انصاف کرسکو، جیسا کہ اس جملے کا معنی ومفہوم ہے: «وَلَا تَتَّبِعَنَّ الْهَوَى لِتَرْضَى رَبَّكَ» تم ہرگز خواہش نفس کی اتباع نہ کرو تا کہ تم اپنے رب کو راضی کر سکو، یعنی میں تجھے خواہش نفس کی پیروی سے منع کرتا ہوں تا کہ تجھ سے تیرا رب راضی ہو جائے اور اگر کسی کو گواہی کی ادائیگی کے لیے بلایا جائے اور وہاں اور بھی گواہ موجود ہوں تو اگر یہ موقع کا گواہ ہے تو اس کے لیے جانا مستحب ہے، اگر نہ جائے تو بھی کوئی مضائقہ نہیں۔ اگر اس کے علاوہ موقع کا کوئی اور گواہ نہیں تو پھر اس کے لیے جانا واجب قرار پائے گا۔ بہت سارے گواہوں کی صورت میں گواہی دینے کے لیے جانا فرض کفایہ کی قبیل سے تعلق رکھتا ہے جیسے سلام کا جواب دینا، میت پر جنازہ پڑھنا اور جہاد کرنا وغیرہ (کہ کچھ افراد اگر ان احکام کی بجا آوری کردیں تو باقی لوگ گنہ گار نہ ہوں گے۔) یہ بھی کہا گیا ہے کہ ’’گواہیاں دیں گے حالانکہ ان سے گواہی طلب نہیں کی جائے گی۔‘‘ سے مراد جھوٹی گواہی ہے (یعنی اس میں ان لوگوں کی مذمت ہے جو جھوٹے ہوں، کسی کا حق مارنے یا کسی دوسرے کو فائدہ پہنچانے کے لیے یہ قسمیں کھائیں اور آگے بڑھ بڑھ کر گواہیاں دیں......) اسی طرح (يَحْلِفُونَ وَلَا يُسْتَحْلَفُونَ) وہ قسمیں کھائیں گے اس معنی کی دلیل یہ ہے کہ بعض روایات میں قرب قیامت کے متعلق (ثُمَّ يَفْشُو الْكَذِبُ) پھر جھوٹ عام ہو جائے گا، کے الفاظ مروی ہیں یعنی ہر طرف جھوٹ اور دروغ گوئی کا دور دورہ ہو جائے گا، چھوٹی گواہیاں اور جھوٹی قسمیں کھانا معمول بن جائے گا۔ یہ بھی کہا گیا ہے کہ گواہیوں سے مراد غیبی امور کے متعلق بڑے دھڑلے سے قسمیں کھانا ہے، مثلاً فلاں جنت میں جائے گا، فلاں آگ میں جائے گا اور اس انداز میں گویا قسم کھانے والا اللہ کو قسم دے رہا ہے کہ وہ ضرور ایسا کرے، فلاں کو جنت میں داخل کرے اور فلاں کو دوزخ میں۔ اس انداز تکلم سے شریعت میں روکا گیا ہے۔ امام احمد رحمہ اللہ نے کہا: ہوسکتا ہے بہترین گواہوں سے مراد وہ گواہ ہوں جو کسی کے اوپر زکاۃ اور کفارہ واجب ہونے کی گواہی دیں نیز رمضان المبارک کا چاند دیکھنے کی گواہی اور دیگر حقوق اللہ کے واجب ہونے کی گواہی طلاق اور آزادی کی گواہی وغیرہ اور دوسری حدیث کے الفاظ ’’وہ گواہیاں دیں گے حالانکہ ان سے گواہی طلب نہیں کی جائے گی‘‘ سے مراد حقوق العباد کی گواہیاں ہیں مثلاً تجارت، اقرار نامے، قصاص اور قذف وغیرہ کی گواہیاں۔ ان میں اس وقت تک گواہی دینا جائز نہیں جب تک عدالت میں دعویٰ دائر نہ کر دیا جائے اور حاکم وقت مدعی کو طلب کر کے گواہی کا مطالبہ نہ کرے۔"}],[2518,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تیری قسم اسی بات پر ہے جس پر تیرا ساتھی تجھ سے تصدیق کرا رہا ہے۔‘‘","",{"k":"أخرجه مسلم: 1653"}],[2519,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قسم اٹھوانے والے کی نیت کے مطابق قسم ہوتی ہے۔‘‘","",{"k":"أخرجه مسلم: 1653","e":"امام ابو عیسی ترمذی رحمہ اللہ نے کہا: اسی حدیث پر بعض اہل علم کا عمل ہے۔ امام احمد اور اسحاق رحمہما اللہ کا قول یہی ہے۔ مروی ہے کہ جناب ابراہیم نخعی نے کہا: اگر قسم اٹھوانے والا ظالم ہو تو قسم اٹھانے والے کی نیت معتبر ہوگی اور اگر وہ مظلوم ہو تو قسم اٹھوانے والے کی نیت کا اعتبار ہوگا۔ (يَمِينُكَ عَلَى مَا يُصَدِّقُكَ صَاحِبُكَ) ’’تیری قسم کا وہی مطلب معتبر ہوگا جس کی تصدیق قسم اٹھوانے والا کرے گا۔‘‘ یعنی قسم اٹھوانے والے کی نیت کے مطابق قسم اٹھانا تیرے لیے واجب ہے اور قسم کا وہی مفہوم معتبر ہو گا جس کی تصدیق قسم طلب کرنے والا کرے گا۔"}],[2520,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’تین قسم کے آدمی ایسے ہیں کہ قیامت کے روز اللہ تعالیٰ ان سے نہ بات کرے گا اور نہ (رحمت کی نگاہ سے) دیکھیے گا، ایک وہ شخص جس نے کسی سودے پر جھوٹی قسم کھائی کہ مجھے اس کی زیادہ قیمت ملتی تھی بہ نسبت موجودہ خریدار کے۔ دوسرا وہ شخص جس نے عصر کے بعد جھوٹی قسم اٹھائی تاکہ اس کے ذریعے سے کسی مسلمان شخص کا مال ہضم کرلے اور تیسرا وہ شخص جس نے ضرورت سے زائد پانی روک لیا (اور کسی کو نہ دیا) اللہ تعالیٰ فرمائے گا، آج میں تجھ سے اپنا فضل وکرم روک لوں گا جس طرح تو نے وہ زائد چیز روک لی تھی جس کو تیرے ہاتھوں نے نہیں بنایا تھا۔‘‘","",{"k":"أخرجه البخارى: 2369، ومسلم: 108","e":"منقول ہے کہ عصر کے وقت کا بطور خاص تذکرہ اس لیے کیا گیا ہے کہ اللہ سبحانہ وتعالیٰ نے اپنی کتاب مجید میں اس وقت کی عظمت اور جلالت کا بطور خاص ذکر کیا ہے، چنانچہ ارشاد ہے:\n﴿ حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى ﴾ [سورہ بقرہ: ۲۳۸]\n’’نمازوں کی حفاظت کرو، بالخصوص درمیان والی نماز کی۔‘‘\nصحابہ کرام کی ایک جماعت سے مروی ہے کہ صلوۃ وسطی سے مراد عصر کی نماز ہے۔ اس میں رات اور دن کے فرشتوں کا اکٹھ ہوتا ہے اور دن کے آغاز سے لے کر عصر تک جو اعمال انسان نے کیے ہوتے ہیں وہ اللہ کے حضور بلند ہوتے ہیں اور جس چیز سے اس وقت کی حرمت میں مزید تاکید ہو جاتی ہے اللہ سبحانہ وتعالیٰ کا یہ فرمان ہے:\n﴿ تَحْبِسُونَهُمَا مِنْ بَعْدِ الصَّلَاةِ فَيُقْسِمَانِ بِاللَّهِ ﴾ [سورہ مائدہ: ۱۰۶]\n’’دونوں کو بعد نماز روک لو پھر دونوں اللہ کی قسم کھائیں۔‘‘\nکہا گیا ہے کہ اس آیت کریمہ میں نماز سے مراد عصر ہی کی نماز ہے۔ امام خطابی رحمہ اللہ نے کہا: اس وقت کی اہمیت، حرمت اور نزاکت کے حوالے سے کہا جاسکتا ہے کہ عام طور پر ایک تاجر شخص دن بھر کا کمایا ہوا مال اور اپنی تجارت کا حاصل دن کی سفیدی میں خرچ کرتا ہے (یعنی سرمایہ ادھر ادھر منتقل کرتا ہے یا شام کے جھٹپٹے سے پہلے اپنے بچوں کے لیے اشیائے ضرورت خرید لیتا ہے) اور بسا اوقات ایسا دن بھی آسکتا ہے کہ عصر کے بعد کا وقت جو اس کے گھر اور بال بچوں میں لوٹنے کا وقت ہے، اس وقت تک اسے کچھ منافع بھی حاصل نہ ہو اور جب کوئی گاہک آئے تو جھوٹی قسم کھا کر اسے پھنسانے کی کوشش کرے تا کہ جاتے جاتے جو منافع ملتا ہے وہ تو ملے اور بالکل بے نیل مرام گھر واپس نہ جائے، اس لیے شریعت نے اس وقت کی سنگینی کو دو چند کر دیا ہے۔ امام بغوی رحمہ اللہ نے کہا: جب کسی شخص کو کسی مہتم بالشان کام پر قسم اٹھانا پڑے مثلاً قصاص، حد، نکاح، طلاق، آزادی اور مال کا نصاب کو پہنچنا وغیرہ تو بعض مقامات اور اوقات کی بنا پر قسم کی اہمیت مزید بڑھ جاتی ہے، مثلاً اگر وہ شخص مکہ میں موجود ہے تو رکن اور مقام ابراہیم کے درمیان قسم کھانا، اور اگر مکہ میں موجود نہیں تو کسی مسجد کے منبر پر چڑھ کر قسم کھانا (ریاض الجنہ اور منبر نبوی پر قسم کھانا) اور اوقات میں سے عصر کے بعد قسم کھانا ہے۔ قسم اٹھانے والے کو اللہ کا خوف یاد دلایا جائے اور اس کو اللہ عزوجل کا یہ فرمان پڑھ کر سنایا جائے۔\n﴿ إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا ﴾ [آل عمران: ۷۷]\n’’بے شک جو لوگ اللہ تعالیٰ کے عہد اور اپنی قسموں کو تھوڑی قیمت پر بیچ ڈالتے ہیں۔‘‘\nتاکہ وہ کانپ جائے اور اس کا دل دھل جائے اگر وہ باطل اور جھوٹی قسم کھانے والا ہے۔ مفسرین نے اللہ تعالیٰ کے فرمان:\n﴿ تَحْبِسُونَهُمَا مِنْ بَعْدِ الصَّلَاةِ ﴾ [سورہ مائدہ: ۱۰۶]\n’’تم ان دونوں کو بعد نماز روک لو۔‘‘\nکے متعلق کہا کہ اس آیت میں نماز سے مراد، عصر کی نماز ہے اور بعد از عصر قسم کھانے والے پر قسم کی سنگینی اور تاکید بڑھ جاتی ہے۔ امام شافعی رحمہ اللہ نے کہا: مکہ کے حکام اور مفتیوں کا یہی قول ہے اور ان کی دلیل یہ واقعہ ہے کہ ایک مرتبہ سیدنا عبدالرحمن بن عوف رضی اللہ عنہ نے کچھ لوگوں کو بیت اللہ اور مقام ابراہیم کے درمیان قسم اٹھاتے دیکھا تو دریافت کیا کہ کیا کسی خون کے معاملے پر قسم کھائی جارہی ہے؟ لوگوں نے کہا: نہیں، عبدالرحمن بن عوف رضی اللہ عنہ نے دریافت کیا: کسی بڑے معاملے پر قسم کھائی جارہی ہے؟ لوگوں نے کہا: نہیں۔ حضرت نے کہا: میں ڈرتا ہوں کہیں لوگ اس مقام کی اہمیت سے لاپرواہی نہ برتنے لگیں۔ ابن ابی ملیکہ نے بیان کیا: میں نے سیدنا ابن عباس رضی اللہ عنہ کو دو لونڈیوں کے بارے میں لکھا جن میں سے ایک نے دوسری کو مارا تھا اور ان میں سے کوئی بھی مان نہیں رہی تھی تو انہوں نے لکھ بھیجا کہ ان کو عصر کی نماز کے بعد روک لو اور ان پر یہ آیت کریمہ تلاوت کرو:\n﴿ إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا ﴾ [آل عمران: ۷۷]\n’’بے شک جو لوگ اللہ تعالیٰ کے عہد اور اپنی قسموں کو تھوڑی قیمت پر بیچ ڈالتے ہیں۔‘‘\nچنانچہ میں نے ایسے ہی کیا تو ان میں سے ایک نے اپنے جرم کا اعتراف کر لیا۔ سیدنا ابوبکر صدیق رضی اللہ عنہ کے سیکرٹری منبر رسول کے پاس قسم لیتے تھے اور عثمان رضی اللہ عنہ نے منبر رسول پر قسم لینے سے منع کر دیا اور اس سے اجتناب کیا اور کہا: مجھے خطرہ ہے کہ اس پر کوئی مصیبت تقدیر کے مطابق آجائے مگر کہا جائے کہ ان کے قسم لینے کی وجہ سے آئی ہے۔ (سنن بیہقی: ۱۷۷/۱۰)"}],[2521,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کسی مسلمان شخص کا خون حلال نہیں جو اس بات کی گواہی دیتا ہے کہ صرف اللہ معبود برحق ہے اور میں اللہ کا رسول ہوں البتہ تین باتوں میں سے ایک بات کی وجہ سے حلال ہے۔ شادی شدہ زنا کرنے والے، نفس کو نفس کے بدلے (قصاصاً)، دین اسلام کو چھوڑ کر مسلمانوں کی جماعت سے الگ ہو جانے والا۔‘‘","",{"k":"أخرجه البخارى: 6878، ومسلم: 1676"}],[2522,"جناب ابو امامہ بن سہل بیان کرتے ہیں کہ میں سیدنا عثمان رضی اللہ عنہ کے ہاں موجود تھا جبکہ وہ اپنے گھر میں محصور تھے۔ سیدنا عثمان رضی اللہ عنہ نے دریافت کیا: تم مجھے کیوں قتل کرنا چاہتے ہو؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ’’کسی مسلمان کا خون حلال نہیں، سوائے اس کے کہ اس سے تین باتوں میں سے کوئی ایک صادر ہو: وہ شخص جس نے اسلام قبول کرنے کے بعد کفر کیا، یا شادی شدہ ہونے کے بعد زنا کیا یا قصاص کے بغیر کسی کو قتل کر دیا، تو اسے ان کے بدلے میں قتل کر دیا جائے گا۔‘‘ اور اللہ کی قسم! میں نے کبھی زنا نہیں کیا، جاہلیت میں نہ اسلام لانے کے بعد۔ اور جب سے اللہ نے مجھے ہدایت نصیب فرمائی ہے میں نے کبھی نہیں چاہا کہ میرا اس (اسلام) کے بدلے کوئی اور دین ہوتا، اور میں نے کسی کو قتل بھی نہیں کیا ہے، تو پھر تم میرے قتل کے درپے کیوں ہو؟","",{"k":"صحيح: أخرجه ابوداود: 4502، والترمذى: 2158، وابن ماجه: 2533"}],[2523,"سیدنا ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مومن ہمیشہ فراخی میں رہتا ہے (یعنی اس کو نیک اعمال کی توفیق ملتی ہے۔) جب تک وہ ناحق خون نہیں بہاتا۔‘‘","",{"k":"أخرجه البخارى: 6862، 6863","e":"سیدنا ابودرداء رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «لَا يَزَالُ الْمُؤْمِنُ مُعْنِقًا صَالِحًا مَا لَمْ يُصِبْ دَمًا حَرَامًا، فَإِذَا أَصَابَ دَمًا حَرَامًا بَلَّحَ»...... ’’مومن ہمیشہ بڑا ہلکا پھلکا اور اچھے اعمال کی توفیق میں رہتا ہے جب تک کہ کسی حرام خون کا مرتکب نہ ہو، جب وہ اس کا مرتکب ہو جاتا ہے تو اس توفیق سے محروم ہو جاتا ہے۔‘‘ الْمُعْنِقُ سے مراد ہلکا پھلکا، بغیر وزن اور بوجھ کے یعنی وہ ہلکے پھلکے آدمی کی طرح چلتا ہے۔ العنق اونٹوں کی ایک خاص چال کو کہتے ہیں۔ (بَلَّحَ) تھک جاتا ہے اور اس کا چلنا موقوف ہو جاتا ہے۔ جب گھوڑا تھک ٹوٹ کر گر جائے اور بالکل نہ چل سکے تو بَلَّحَ الْفَرَسُ کا لفظ بولا جاتا ہے۔ اسی طرح جب کنواں خشک ہو جائے اور ایک قطرہ پانی کا نہ رہے تو بَلَّحَتِ الرَّكِيَّةُ کہا جاتا ہے۔ جناب حسن بصری رحمہ اللہ نے کہا: یہ مثال اس وقت بولی جاتی ہے جب کوئی کسی کو قتل کر دے (تو اس کی اپنی حالت خراب ہو جاتی ہے) یا کسی کو قتل نہ کرے (تو رحمت الہی اس کے شامل حال رہتی ہے۔)"}],[2524,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’(قیامت کے دن) سب سے پہلے لوگوں کے درمیان خونوں کا فیصلہ ہوگا۔‘‘","",{"k":"أخرجه البخارى: 6864، ومسلم: 1678","f":"ایک حدیث مبارکہ میں مذکورہ ہے کہ سب سے پہلے نمازوں کا محاسبہ ہوگا۔ ان دونوں احادیث کے درمیان تعارض اس طرح ختم کیا جاسکتا ہے کہ حقوق اللہ میں سے سب سے پہلے نمازوں کا فیصلہ ہوگا اور حقوق العباد میں سے سب سے پہلے خونوں کا۔ واللہ اعلم"}],[2525,"سیدنا مقداد بن اسود رضی اللہ عنہ بیان کرتے ہیں کہ میں نے دریافت کیا: اے اللہ کے رسول! اگر میری اور مشرکوں میں سے کسی شخص کی دو ضربیں ہو جائیں اور وہ میرا ایک ہاتھ کاٹ دے، پھر جب میں اس کی طرف قتل کے ارادے سے حملہ آور ہوں تو وہ ’’لا الہ الا اللہ‘‘ کہہ دے۔ تو کیا میں اسے قتل کر دوں یا چھوڑ دوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’بلکہ تو اسے چھوڑ دے۔‘‘ سیدنا مقداد نے کہا: اس نے دریافت کیا: اگرچہ اس نے میرا ہاتھ کاٹا ہو؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’خواہ اس نے ایسا کیا ہو۔‘‘ میں نے یہ بات آپ سے دو مرتبہ یا تین مرتبہ دہرائی تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’اگر تو نے اسے ’’لا الہ الا اللہ‘‘ پڑھنے کے بعد قتل کر دیا تو تو اس جیسا ہوگا جیسے وہ کلمہ کہنے سے پہلے تھا۔ اور وہ تجھ جیسا ہوگا جیسے تو اس کو قتل کرنے سے پہلے تھا۔‘‘","",{"k":"أخرجه البخارى: 4019، 6865، ومسلم: 95","e":"امام بغوی رحمہ اللہ نے کہا: جو لوگ کسی مسلمان کو کبیرہ گناہ کے ارتکاب کی وجہ سے کافر سمجھتے ہیں وہ اس حدیث مبارکہ سے استدلال کرتے ہیں اور وہ خوارج ہیں اور وہ حدیث میں وارد الفاظ ’’مِثْلُهُ‘‘ کا یہ مطلب بیان کرتے ہیں کہ وہ کفر میں اس جیسا ہے لیکن اہل السنہ کے نزدیک ان الفاظ کا یہ مطلب ہے کہ وہ اس جیسا ہے خون کو مباح سمجھنے میں نہ کہ کفر میں۔ یاد رہے! مسلمان جب کسی دوسرے مسلمان کو قتل کرتا ہے تو قتل کرنے والا اپنے خون کو حلال قرار دیتا ہے، چنانچہ قصاصاً اسے قتل کر دیا جائے گا جیسے کافر شخص کو اختلاف دین کی بنا پر قتل کرنا مباح اور جائز ہے۔ حدیث مبارکہ سے پتہ چلا کہ ایک کافر شخص جب کلمہ شہادت پڑھ لے اگرچہ ایمانیات کی باقی تفصیل سے نابلد ہی ہو تو اسے قتل کرنے سے رک جانا واجب ہے خواہ اس پر قدرت پائی جاتی ہو یا نہ۔","f":"اسلام لانے کے بعد کسی شخص کے قتل کو جائز سمجھنا کفر ہے، اسے جائز سمجھ کر جو قتل کرے گا وہ کافر ہو گا۔ مقصود یہ ہے کہ ’’لا الہ الا اللہ‘‘ کہنے کے بعد اس کو قتل کرنا حرام ہو گیا۔ واللہ اعلم"}],[2526,"سیدنا ابوبکرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’بلاشبہ جنت کی خوشبو ایک سو سال کے فاصلے سے محسوس ہوتی ہے اور جو شخص کسی ذمی کو قتل کرتا ہے تو اس پر اللہ تعالیٰ جنت کو حرام کر دیتے ہیں اور وہ اس کی خوشبو بھی نہیں پا سکے گا۔‘‘ سیدنا ابوبکرہ رضی اللہ عنہ نے کہا: اگر میں نے رسول اللہ صلی اللہ علیہ وسلم کو یونہی فرماتے ہوئے نہ سنا ہوتا تو اللہ تعالیٰ میرے کانوں کو بہرا کر دے۔","",{"k":"صحيح: أخرجه ابوداود: 2760، والنسائى: 4761","e":"سیدنا ابن عمر رضی اللہ عنہما سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «مَنْ قَتَلَ مُعَاهَدًا لَمْ يَرِحْ رَائِحَةَ الْجَنَّةِ، وَإِنَّ رِيحَهَا تُوجَدُ مِنْ مَسِيرَةِ أَرْبَعِينَ عَامًا»...... ’’جو شخص کسی ذمی کو قتل کرے اسے جنت کی خوشبو نہیں آئے گی، حالانکہ اس کی خوشبو چالیس سال کے فاصلے سے محسوس ہوتی ہے۔‘‘ (صحیح بخاری: ۳۱۶۶) سیدنا ابو ہریرہ رضی اللہ عنہ کی روایت میں (مِنْ مَسِيرَةِ سَبْعِينَ خَرِيفًا) ’’ستر سال کی مسافت سے (محسوس ہوتی ہے) کے الفاظ ہیں۔ (صحیح، ترمذی: ۱۴۰۳، ابن ماجہ: ۲۶۸۷)","f":"ایسا شخص جو کافر ہوتے ہوئے حکومت اسلامیہ میں رہ رہا ہو اور ٹیکس وغیرہ ادا کرتا ہو تو اسے ذمی اور معاہد کہتے ہیں۔ (ع، س) (لَمْ يَرِحْ رَائِحَةَ الْجَنَّةِ) ’’وہ جنت کی خوشبو نہیں پائے گا۔‘‘ ابوعبید نے کہا: لَمْ يَرِحْ کا لفظ راء کے فتحہ کے ساتھ، رحت اراح کے باب سے اور اس کا معنی ہے: خوشبو محسوس کرنا، ابوعمرو نے کہا: یہ لفظ راء کے نیچے زیر کے ساتھ ہے یعنی رَحْتُ أَرِيحُ یعنی خوشبو پانا، امام کسائی نے کہا: یہ لفظ کے اوپر پیش کے ساتھ ہے، یعنی لَمْ يُرِحْ. جب آپ کوئی خوشبو محسوس کریں گے تو کہیں گے: أَرِحْتُ الشَّيْءَ فَأَنَا أُرِيحُهُ (اس لحاظ سے یہ مزید فیہ کا باب ہوگا مجرد کا نہیں)"}],[2527,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے خود کو نیزہ مار کر خودکشی کی، تو نیزہ اس کے ہاتھ میں ہوگا اور وہ ہمیشہ ہمیشہ کے لیے جہنم کی آگ میں اپنے پیٹ میں اس نیزے کو چبھوتا رہے گا اور جس شخص نے زہر پی کر خودکشی کی تو زہر کا پیالہ اس کے ہاتھ میں ہوگا وہ دوزخ میں ہمیشہ ہمیشہ کے لیے زہر کے پیالے سے گھونٹ گھونٹ پیتا رہے گا، اور جس شخص نے پہاڑ (کی بلندی) سے خود کو گرا کر خودکشی کی، وہ ہمیشہ ہمیشہ دوزخ کی آگ میں خود کو گراتا رہے گا۔‘‘","",{"k":"أخرجه البخارى: 5778، ومسلم: 109","f":"خودکشی کرنا کبیرہ گناہ ہے اور جمہور اہل سنت کا موقف ہے کہ کبیرہ گناہوں کا مرتکب سزا بھگتنے کے بعد جنت میں جائے گا ’’الا ان یشاء اللہ‘‘ تو پھر جن احادیث میں آتا ہے کہ اس پر جنت حرام ہے، یا جنت میں داخل نہیں ہوگا، ان کا مفہوم یہ ہے کہ ایسا مسلمان جنت میں جانے والے اولین لوگوں میں شامل نہیں ہوگا۔ یہ معنی نہیں کہ وہ جنت میں جائے گا ہی نہیں، کیونکہ اللہ کا وعدہ ہے کہ اہل توحید جنت میں داخل ہوں گے۔ یا اس سے مقصود لمبا اور طویل عرصہ ہے یہ بھی ممکن ہے کہ حدیث کے اس مفہوم کو شدید وعید پر محمول کیا جائے۔ (ع، س)"}],[2528,"جناب ثابت بن ضحاک بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دنیا میں جس چیز کے ساتھ کسی نے اپنے آپ کو قتل کیا، قیامت والے دن اسی کے ساتھ اسے عذاب میں مبتلا کیا جائے گا۔‘‘","",{"k":"أخرجه البخارى: 1363، ومسلم: 110"}],[2529,"جناب حسن بصری رحمہ اللہ نے بیان کیا کہ ہم سے اسی مسجد میں سیدنا جندب بن عبداللہ رضی اللہ عنہ نے بیان کیا، انہوں نے جب سے ہمیں بیان کیا ہم اسے بھولے نہیں اور نہ ہمیں اس کا اندیشہ ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کی طرف اس حدیث کی نسبت غلطی کی ہوگی۔ انہوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پچھلے زمانے کے لوگوں میں ایک شخص کو (ہاتھ پر) کوڑھ ہو گیا۔ وہ اس سے تنگ آگیا۔ آخر اس نے چھری نکالی اور اس سے اپنا ہاتھ کاٹ لیا، اس کا خون بہنے لگا اور اسی سے وہ مر گیا۔‘‘ اس پر اللہ تعالیٰ نے فرمایا: میرے بندے نے خود میرے پاس آنے میں جلدی کی اس لیے میں نے بھی جنت کو اس پر حرام کر دیا۔‘‘","",{"k":"أخرجه البخارى: 3463، ومسلم:","e":"ایک اور سند میں یہ الفاظ مذکور ہیں (خَرَجَ بِرَجُلٍ فِيمَنْ كَانَ قَبْلَكُمْ خُرَاجٌ) ’’گزشتہ زمانے میں ایک شخص کو پھوڑا نکل آیا۔‘‘"}],[2530,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ ہم رسول اکرم صلی اللہ علیہ وسلم کے ساتھ جنگ خیبر میں موجود تھے، رسول اللہ صلی اللہ علیہ وسلم نے اپنے ساتھیوں میں سے ایک شخص کے متعلق جو اپنے آپ کو مسلمان کہتا تھا، فرمایا: ’’یہ شخص آگ والوں میں سے ہے۔‘‘ جب جنگ شروع ہوئی تو وہ شخص (مسلمانوں کی طرف سے) بڑی بہادری کے ساتھ لڑا اور اسے بہت سارے زخم لگے اور وہ ثابت قدم رہا، اصحاب نبی میں سے ایک شخص نے آکر کہا: اے اللہ کے رسول! جس کے بارے میں آپ نے فرمایا تھا کہ وہ آگ والوں میں سے ہے، اس نے اللہ کے راستے میں بڑی جگری سے قتال کیا ہے اور اسے بہت زیادہ زخم پہنچے ہیں۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’خبردار! وہ دوزخ والوں میں سے ہے۔‘‘ ممکن تھا کہ بعض لوگوں کے دل میں کچھ شبہ پیدا ہو جاتا۔ وہ ابھی زخمی حالت ہی میں تھا کہ اس نے زخموں کی سخت تکلیف محسوس کی اور اپنے ہاتھ کو ترکش کی طرف بڑھایا اور اس میں سے ایک تیر نکال کر خودکشی کرلی۔ مسلمانوں میں سے لوگ دوڑے دوڑے اللہ کے رسول صلی اللہ علیہ وسلم کے پاس آئے اور آکر عرض کی: اے اللہ کے رسول! اللہ نے آپ کی بات کو سچ کر دیا ہے، فلاں نے گلا کاٹ کر خودکشی کرلی ہے۔ اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا: ’’اے بلال! اٹھو اور اعلان کر دو کہ مومن کے سوا جنت میں کوئی اور داخل نہیں ہوگا اور بلاشبہ اللہ تعالیٰ اپنے دین کی امداد کسی فاجر شخص سے بھی کرا لیتا ہے۔‘‘","",{"k":"أخرجه البخارى: 3062، 4203، ومسلم: 111","e":"عبدالرزاق نے جناب معمر سے بیان کیا کہ ہم غزوہ حنین میں شریک تھے۔ سیدنا جابر بن سمرہ رضی اللہ عنہ نے بیان کیا کہ ایک شخص نے خودکشی کرلی تو نبی اکرم صلی اللہ علیہ وسلم نے اس کا جنازہ نہیں پڑھایا۔"}],[2531,"سیدنا وائل بن حجر رضی اللہ عنہ کا بیان ہے کہ میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر تھا کہ ایک قاتل لایا گیا، اس کی گردن میں چمڑے کی ایک پٹی (بندھی ہوئی) تھی، آپ نے مقتول کے ولی کو بلایا اور اس سے کہا: ’’کیا تم معاف کرتے ہو؟‘‘ اس نے کہا: نہیں۔ آپ نے پوچھا: ’’کیا تم دیت لینا قبول کرتے ہو؟‘‘ اس نے کہا: نہیں۔ آپ نے پوچھا: ’’کیا قتل کرو گے؟‘‘ اس نے کہا: ہاں آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جاؤ اسے لے جاؤ۔‘‘ پھر چوتھی بار فرمایا: ’’اگر تم اس کو معاف کر دو تو یہ اپنے اور مقتول دونوں کے گناہ اپنے سر لے گا۔‘‘ راوی نے کہا: چنانچہ اس نے اس کو معاف کر دیا۔ وائل کہتے ہیں کہ میں نے قاتل کو دیکھا کہ وہ اپنی پٹی گھسیٹتے جارہا تھا۔","",{"k":"أخرجه مسلم: 1680","e":"حدیث ہذا میں اس بات کی دلیل ہے کہ مقتول کے ولی کو اس بات کا اختیار حاصل ہے کہ وہ قصاص لے لے یا قصاص کی بجائے دیت لے لے یا دیت لیے بغیر محض رضائے الہی کے لیے معاف کر دے۔ امام شافعی رحمہ اللہ کا اس بارے میں قول مختلف ہے کہ اگر مقتول کا وارث قاتل کو مطلقاً معاف کر دے تو کیا اس صورت میں دیت لینا واجب ہوگا یا نہیں؟ امام شافعی رحمہ اللہ کے صحیح قول کے مطابق دیت کا حصول واجب نہیں الا یہ کہ قصاص کی بجائے دیت ہی پر معاف کیا جائے۔ حدیث مبارکہ سے پتہ چلا کہ قتل عمد کی دیت قاتل کے مال ہی سے وصول کی جائے گی۔ حدیث سے معلوم ہوا کہ حاکم یا قاضی کو چاہیے کہ وہ مقتول کے ولی کو معاف کر دینے کی سفارش کریں۔ سیدنا انس رضی اللہ عنہ سے مروی ہے کہتے ہیں: میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس جب بھی کوئی ایسا مقدمہ لایا جاتا جس میں قصاص ہوتا تو آپ معاف کرنے کا فرماتے۔ (صحیح، ابوداود: ۴۴۹۷، نسائی: ۴۷۹۷، ابن ماجہ: ۲۶۹۲) حدیث مبارکہ میں اس بات کی دلیل ہے کہ جب قاتل (مجرم) کے بھاگ جانے کا اندیشہ ہو تو اسے رسیوں سے باندھا اور محبوس کیا جاسکتا ہے۔ حدیث مبارکہ اس بات پر بھی دلالت کرتی ہے کہ قاتل کو جب معاف کر دیا تو اسے جانے دیا جائے اور اس کا راستہ نہ روکا جائے اور یہ کہ اس کو تعزیر نہ لگائی جائے۔ امام مالک رحمہ اللہ سے بیان کیا جاتا ہے کہ انہوں نے کہا: معاف کر دینے کے بعد قاتل کو سو کوڑے مارے جائیں اور ایک سال تک قید و بند میں رکھا جائے۔ (يَبُوءُ بِإِثْمِهِ وَإِثْمِ صَاحِبِهِ) ’’یہ اپنے اور اپنے مقتول دونوں کے گناہ اپنے سر لے گا‘‘، یعنی مقتول کے علاوہ سب گناہوں کا بوجھ اسے اٹھانا ہو گا اور بروز قیامت جوابدہ ہونا پڑے گا اور اگر قصاصاً قتل کر دیا جائے تو بسا اوقات ایسا مرنا اس کے تمام گناہوں کا کفارہ بن جاتا ہے اور مقتول کو قتل کرنے کے گناہ کا بھی۔ یعنی اپنے مسلمان بھائی کو قتل کر دینے کا جو گناہ اس کے ذمے آتا ہے اس سے بھی بری ہو جاتا ہے۔ حدیث مبارکہ کے الفاظ میں گناہ کو مقتول کی طرف مضاف کیا گیا ہے اس لیے کہ اس کا قتل کیا جانا قاتل کے گنہگار ہونے کا سبب ہے۔ یہ اضافت ایسے ہی ہے جیسا کہ اللہ سبحانہ وتعالیٰ کے فرمان میں لفظ رسول کی اضافت لوگوں کی جانب کی گئی ہے حالانکہ آپ اللہ کے رسول ہیں جنہیں اللہ نے ان کی طرف مبعوث فرمایا ہے ارشاد باری تعالی ہے:\n﴿ إِنَّ رَسُولَكُمُ الَّذِي أُرْسِلَ إِلَيْكُمْ لَمَجْنُونٌ ﴾ [الشعراء: ۲۷]\n’’(فرعون نے کہا: لوگو!) تمہارا یہ رسول جو تمہاری طرف بھیجا گیا ہے یہ تو یقیناً دیوانہ ہے۔‘‘\nاسی حدیث میں مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (مقتول کے ولی سے) کہا: ’’اسے پکڑ لو۔‘‘ وہ اسے لے کر نکلا تا کہ قتل کر دے، اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر اس نے اس کو قتل کر دیا تو یہ بھی اس جیسا ہوگا۔‘‘ (دیکھیے: حدیث نمبر ۲۵۲۷) یہ بھی کہا گیا ہے کہ ایک جیسا ہونے کا مفہوم یہ ہے کہ بوجھ اٹھانے اور بطور انجام ایک جیسے ہو جائیں گے، یعنی اگر قصاص لینے والے نے معاف نہ کیا بلکہ پورا پورا حق وصول کیا تو اس کے اور قاتل کے مابین کوئی اخلاقی تفاوت باقی نہیں رہتا۔ بعض کے نزدیک ان الفاظ سے آپ کا مقصود مقتول کے وارث کو قاتل کے قتل سے روکنا، ڈانٹنا اور باز رکھنا تھا کیونکہ قاتل بار بار کہتا تھا کہ مجھ سے ارادۂ قتل نہیں ہوا، اگر واقعی اس کا قتل کرنے کا ارادہ نہیں تھا اور اس کے باوجود مقتول کے ولی نے اسے قصاصاً قتل کر دیا، اور اس کا عذر سن کر معاف نہیں کیا تو اس کا معاملے قاتل کے معاملہ سے ہم آہنگ اور مماثل ہے، کوئی فرق نہیں بلکہ اسے بطور قصاص مارنا لازم آتا ہے الا یہ کہ یہ ثابت ہو جائے کہ قاتل نے جان بوجھ پر قتل کیا ہے۔ ہمارے اس موقف پر سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی حدیث مبارکہ دلالت کرتی ہے کہ نبی کریم صلی اللہ علیہ وسلم کے زمانے میں ایک آدمی قتل ہو گیا اور اس کا مقدمہ نبی کریم صلی اللہ علیہ وسلم کے سامنے پیش کیا گیا تو آپ نے قاتل کو مقتول کے وارث کے حوالے کر دیا۔ قاتل نے کہا: اے اللہ کے رسول: اللہ کی قسم! میں نے اس کے قتل کا ارادہ نہیں کیا تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے اس کے وارث سے فرمایا: ’’خبردار! اگر یہ سچا ہوا اور تو نے اس کو قتل کر دیا تو تو جہنم میں جائے گا۔‘‘ چنانچہ اس نے اس شخص کو چھوڑ دیا۔ (صحیح، ابوداود: ۴۴۹۸، ترمذی: ۱۴۰۷، ابن ماجہ: ۲۶۹۰) حدیث مبارکہ سے معلوم ہوا کہ اگر کسی شخص سے قتل صادر ہو جائے اور اس کا ارادہ قتل کرنے کا نہ ہو اور یہ چیز پایہ ثبوت کو پہنچ جائے تو اس پر قصاص نہیں اور اگر مقتول کا وارث اسے قتل کر دے تو وہ گنہگار ہو گا اور اس پر قصاص واجب ہے۔ قتل کی تین اقسام ہیں: (۱)...... قتل عمد: اس سے مراد ایسا قتل ہے جس سے مکلف شخص کسی قتل کے غیر مستحق شخص کو ایسے آلے سے قتل کرنے کی نیت کرے جس میں اغلب گمان یہی ہو کہ وہ اسے قتل کر دے گا (مثلاً، بندوق، تلوار یا تیر وغیرہ) اس صورت میں قاتل پر قصاص واجب ہے یا دیت مغلظہ کی ادائیگی ضروری ہے جسے مجرم کی جائداد سے وصول کیا جائے گا۔ (۲)...... قتل شبہ عمد: وہ قتل جس میں مکلف کسی کو ایسی چیز سے مارنے کا ارادہ کرے جس سے عموماً انسان مرتا نہیں مثلاً ہلکی چھڑی، کنکری یا چھوٹا تیر وغیرہ اور اس سے وہ شخص مرجائے، اس میں قصاص نہیں بلکہ دیت مغلظہ واجب ہوگی جس کی ادائیگی قاتل کے عصبہ (باپ کی طرف کے رشتہ دار) پر ہوگی اور اسے تین سال کے اندر اندر ادا کرنا ہوگا۔ اگر مضروب بچہ ہو یا ایسے مرض میں مبتلا ہو جس سے عام طور پر آدمی مرجاتا ہے خواہ بظاہر موٹا تازہ ہو اور ضارب (مارنے والے) نے اس کو مارا اور وہ مر گیا تو قصاص لازم آئے گا۔ (۳) قتل خطا: یہ ہے کہ مارنا کسی اور کو ہو لیکن قتل کوئی اور ہو جائے مثلاً کوئی کنواں کھودے تو اس میں گر جائے یا بے محل جال لگا دے جس میں الجھ کر کوئی شخص مرجائے (یا شکاری گولی تو شکار کی طرف چلائے لیکن کسی انسان کو لگ جائے) اس میں قصاص نہیں اس میں آسان دیت واجب ہے جس کی ادائیگی تین سال کی مدت میں میت کے عصبی رشتہ داروں پر واجب ہے۔"}],[2532,"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ ایک لونڈی جس نے زیورات پہنے ہوئے تھے (گھر سے) نکلی، اسے ایک یہودی نے پکڑ لیا اور اس کے سر کو کچل دیا اور اس کے زیورات اتار لیے، اس کے اندر ابھی زندگی کی رمق باقی تھی کہ اسے پالیا گیا اور اسے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں لایا گیا، آپ نے دریافت فرمایا: کس نے تجھے قتل کیا ہے؟ فلاں نے: اس نے اپنے سر کے اشارے سے کہا: نہیں۔ آپ نے پوچھا: فلاں نے؟ حتی کہ آپ نے یہودی کا نام لیا، اس نے اپنے سر کے اشارے سے، ہاں کہا، چنانچہ یہودی کو گرفتار کیا گیا، اس نے اقرار کیا، نبی صلی اللہ علیہ وسلم نے حکم دیا تو اس کے سر کو دو پتھروں کے درمیان رکھ کر کچل دیا گیا۔","",{"k":"أخرجه البخارى: 2413، 2746، ومسلم: 1672","e":"(عَلَيْهَا أَوْضَاحٌ) ابو عبید نے کہا: اس سے مراد چاندی کے زیورات ہیں۔ باقی لغویوں نے کہا: وضح کے لغوی معنی سفیدی اور چمک دمک کے ہیں چاندی کے زیورات کو اوضاح کہنے کی وجہ یہ ہے کہ وہ چمکدار اور سفید ہوتے ہیں۔ حدیث مبارکہ میں اس بات کی دلیل ہے کہ عورت کے بدلے مرد کو قصاصاً قتل کیا جا سکتا ہے جس طرح مرد کے بدلے عورت کو کیا جاسکتا ہے، اکثر اہل علم کا یہی قول ہے ماسوائے اس کے کہ جو حسن بصری اور جناب عطاء رحمہما اللہ سے بیان کیا گیا ہے کہ انہوں نے کہا: آدمی کو عورت کے بدلے قتل نہیں کیا جائے گا۔ حدیث مبارکہ سے معلوم ہوا کہ بھاری پتھر سے کسی کو قتل کرنا جس سے عموماً بندہ مرجانے کا امکان ہوتا ہے، قصاص کا موجب ہے، اکثر اہل علم کا یہی قول ہے۔ امام مالک اور امام شافعی رحمہما اللہ کا بھی یہی موقف ہے۔ بعض علماء بھاری پتھر سے قتل کرنے پر قصاص واجب ہونے کے قائل نہیں۔ اہل رائے کا موقف یہی ہے۔ اگر کوئی شخص دوسرے کو ہلاکت آفریں زہر پلا دے تو پلانے والے پر قصاص واجب ہے۔ امام ابو حنیفہ رحمہ اللہ نے کہا: اس پر قصاص واجب نہیں بلکہ دیت واجب ہے۔ اگر ایک شخص نے کھانے میں زہر ملا دیا ہو اور کسی دوسرے شخص نے وہی کھانا اٹھا کر اس کو کھلا دیا اور کھانے والا حقیقت حال سے بے خبر ہونے کی بنا پر کھا گیا اور مر گیا تو ایک قول کے مطابق امام شافعی رحمہ اللہ کھلانے والے پر قصاص واجب قرار دیتے ہیں۔ امام مالک کا بھی یہی قول ہے۔ البتہ اگر ایسی صورت میں کسی نے زہر آلود کھانا اٹھا کر کسی کے سامنے رکھ دیا اور یہ کہتا رہا کہ جناب کھائیے! پھر وہ شخص سامنے دھرا کھانا کھا گیا اور فوت ہو گیا تو کھانا سامنے رکھنے والے پر کچھ واجب نہیں۔ اس حدیث مبارکہ سے پتہ چلا کہ قتل کے لیے جانے کے انداز کا اعتبار کرنا جائز ہے، یعنی جس طرح اس نے قتل کیا اسی طرح قتل کرنا درست ہے مثلاً اگر کسی شخص کو پتھر مار کر یا بلند و بالا پہاڑ سے گرا کر یا جلا کر یا ڈبو کر مارا گیا ہو تو قاتل کو بھی اسی طرح کیفر کردار تک پہنچایا جائے گا۔ امام شعبی رحمہ اللہ اور عمر بن عبد العزیز رحمہ اللہ سے اسی طرح مروی ہے۔ امام مالک، شافعی، احمد اور اسحاق رحمہم اللہ اسی کے قائل ہیں۔ اہل علم کی ایک جماعت کا موقف ہے کہ ایسی صورتوں میں صرف تلوار ہی سے قصاص لیا جائے گا۔ جناب عطاء اسی کے قائل ہیں۔ سفیان ثوری اور اہل رائے بھی یہی موقف رکھتے ہیں۔ یاد رہے! قصاص لینے کی مماثلت (یعنی جس طرح قاتل نے کیا اسی طرح اس کو قتل کرنا) تب ہوگی جب قاتل نے کسی کو ایسے طریقے سے قتل کیا کہ جواباً وہ طریقہ استعمال کرنا از روئے شرع محمدی جائز ہو مثلاً پتھر مار کر کسی کو قتل کرنا۔ شریعت نے اثنائے جہاد میں کافروں کا شکست اور ہزیمت سے دو چار کرنے کے لیے مندرجہ صدر دو طریقوں کو جائز رکھا ہے۔ اسی طرح کسی کو پانی چھوڑ کر، عمارت گرا کر اور بلند و بالا مقامات سے گرا کر مارنا جائز ہے۔ اگر کوئی شخص دوسرے کو شراب پلا پلا کر مارے یا اس کے ساتھ بدفعلی کا ارتکاب کرے جس سے اس کی موت واقع ہو جائے۔ (یا کسی خاتون کے ساتھ زنا کرے اور وہ مرجائے) یا کوئی کسی کو جادو کے ساتھ قتل کر دے تو نتیجاً مجرم کو اسی طرح قتل کرنا جائز نہیں بلکہ تلوار ہی سے قتل کیا جائے گا۔ کیونکہ شریعت محمدیہ میں یہ امور کسی صورت میں بھی جائز نہیں بلکہ ان کا شمار کبائر میں ہوتا ہے۔ وہ تمام امور جن کی حرمت دوسرے پر زیادتی کی وجہ سے ہے اگر کوئی آدمی اس کا مرتکب ہوتا ہے تو اسے اسی طرح ہی سزا دی جائے گی جیسا کہ ارشاد باری تعالی ہے:\n﴿ فَمَنِ اعْتَدَى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدَى عَلَيْكُمْ ﴾ [سورہ بقرہ: ۱۹۴]\n’’جو تم پر زیادتی کرے تم بھی اس پر اسی کے مثل زیادتی کرو جو تم پر کی ہے۔‘‘","f":"اصلاً اوضاح سے مراد چاندی کے زیورات ہی ہیں لیکن پھر اس لفظ کا استعمال ہر قسم کے زیورات کے لیے ہونے لگا۔ (ع، س)"}],[2533,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ ربیع جو کہ ان کی پھوپھی ہیں انہوں نے ایک لڑکی کا دانت توڑ دیا، پھر ان سے معافی کے طلبگار ہوئے لیکن انہوں نے انکار کر دیا، انہوں نے دیت کی پیشکش کی، انہوں نے انکار کر دیا، چنانچہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور قصاص کے علاوہ کسی بات پر راضی نہ ہوئے تو رسول اللہ صلی اللہ علیہ وسلم نے بھی بدلہ لینے کا حکم صادر فرما دیا (یعنی ان کا بھی دانت توڑ دیا جائے) انس بن نضر رضی اللہ عنہ نے عرض کیا: اے اللہ کے رسول! ربیع کا دانت کس طرح توڑا جائے گا؟ نہیں، اس ذات کی قسم جس نے آپ کو حق کے ساتھ مبعوث فرمایا ہے! اس کا دانت نہیں توڑا جائے گا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اے انس! کتاب کا فیصلہ تو بدلہ لینے (قصاص) ہی کا ہے۔‘‘ چنانچہ وہ لوگ راضی ہو گئے اور معاف کر دیا۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بلاشبہ اللہ کے کچھ بندے ایسے بھی ہیں کہ اگر وہ اللہ کی قسم کھالیں تو اللہ تعالیٰ خود ان کی قسم پوری کرتا ہے۔‘‘","",{"k":"أخرجه البخارى: 2703، 2806، ومسلم: 1675","e":"صحیح مسلم میں اس روایت کے الفاظ یوں ہیں کہ سیدنا انس بن نضر رضی اللہ عنہ بیان کرتے ہیں کہ ان کی ہمشیرہ ربیع ام حارثہ نے ایک انسان کو زخمی کر دیا تھا۔ (كِتَابُ اللَّهِ قِصَاصٌ) ’’اللہ کی کتاب میں قصاص ہے۔‘‘ کہا گیا ہے اس سے مراد اللہ تعالیٰ کا یہ فرمان ہے\n﴿ وَكَتَبْنَا عَلَيْهِمْ فِيهَا أَنَّ النَّفْسَ بِالنَّفْسِ وَالْعَيْنَ بِالْعَيْنِ وَالْأَنْفَ بِالْأَنْفِ وَالْأُذُنَ بِالْأُذُنِ وَالسِّنَّ بِالسِّنِّ ﴾ [سورہ مائدہ: ۴۵]\n’’اور ہم نے یہودیوں کے ذمہ تورات میں یہ بات مقرر کر دی تھی کہ جان کے بدلے جان اور آنکھ کے بدلے آنکھ اور ناک کے بدلے ناک اور کان کے بدلے کان اور دانت کے بدلے دانت۔‘‘\nیہ بات ان لوگوں کے قول کے مطابق ہے جن کا موقف ہے کہ سابقہ انبیائے کرام کی شریعتوں پر عمل کرنا ہمارے اوپر لازم ہے جب تک ان کے احکام کا منسوخ ہونا ہماری شریعت میں مذکور نہ ہو جائے۔ یہ بھی کہا گیا ہے کہ (كِتَابُ اللَّهِ الْقِصَاصُ) کے الفاظ سے اللہ عز وجل کے اس فرمان کی طرف اشارہ ہے:\n﴿ وَالْجُرُوحَ قِصَاصٌ ﴾ [سورہ مائدہ: ۴۵]\n’’اور زخموں میں قصاص ہے۔‘‘\nان قراء کی قراءت کے مطابق جو الجروح کو مبتدا بنا کر مرفوع پڑھتے ہیں۔ یہ بھی کہا گیا ہے کہ کتاب اللہ کا یہاں معنی اللہ تعالیٰ کی طرف سے فرض اور مقرر کردہ احکام ہیں جن کو اس نے اپنے نبی اکرم صلی اللہ علیہ وسلم کی زبانی امت پر فرض فرمایا ہے، یعنی قصاص لینا تو فرض ہے۔ اعضائے جسم کے متعلق قصاص کچھ یوں ہے کہ ہر وہ عضو جس کا کوئی قدرتی معلوم جوڑ ہو تو اس کو نقصان پہنچنے کی صورت میں مجرم کا وہی عضو جوڑ سے کاٹ دیا جائے گا مثلاً انگلی جوڑ سے کائی جائے گی، ہاتھ کلائی یا کہنی سے کاٹ دیا جائے گا، ٹانگ کو بھی جوڑ سے کاٹ دیا جائے گا اور قصاص لے لیا جائے گا۔ اسی طرح اگر کوئی دانت اکھاڑ دے، زبان کاٹ دے، ناک یا کان کاٹ دے، آنکھ پھوڑ دے، آلہ تناسل یا خصیتین کاٹ دے تو قصاص لیا جائے گا۔ اسی طرح اگر کوئی شخص دوسرے کے سر پر چوٹ لگا دے جس سے ہڈی ننگی ہو جائے یا چہرے پر ایسا ہی زخم کر دے تو اس سے قصاص لیا جائے گا اور اگر کوئی شخص دوسرے کے سر پر ہلکا زخم لگا دے جو موضحہ سے کم ہو یا سر کے علاوہ جسم کے کسی اور حصہ پر ایسی ہی چوٹ لگا دے یا ہڈی کو توڑ دے تو ان صورتوں میں اس پر قصاص نہیں ہوگا کیونکہ ایسی صورتوں میں پوری طرح مماثلت ممکن نہیں۔ اسی طرح اگر کوئی شخص دوسرے کا بازو درمیان سے توڑ دے تو قصاص میں بازو نصف کلائی سے نہیں بلکہ جوڑ یعنی کہنی سے کاٹا جائے گا اور باقی نصف کا ہرجانہ ادا کرنا ہوگا۔ تھپڑ اور خراش یا رگڑ لگانے پر کوئی قصاص نہیں۔ اس میں ادب سکھانے اور آئندہ باز رکھنے کے لیے تعزیر ہے اور اگر مضروب کے جسم پر ان چیزوں کا نشان باقی رہ جائے تو ضارب سے ہرجانہ وصول کیا جائے گا۔ اس بات کے قائل حسن بصری، قتادہ، مالک، شافعی اور اہل رائے ہیں۔ اہل علم کی ایک جماعت کا خیال ہے کہ تھپڑ یا چھڑی کی ایک ضرب کا قصاص لیا جائے گا۔ خلفائے راشدین رضی اللہ عنہم سے اسی طرح مروی ہے۔ شریح، شعبی، اور ابن شبرمہ رحمہم اللہ بھی اسی طرف گئے ہیں۔ سیدنا ابو بکرہ رضی اللہ عنہ سے مروی ہے کہ انہوں نے تھپڑ کا قصاص دلوایا تھا۔ سیدنا علی، ابن زبیر اور سوید بن مقرن رضی اللہ عنہم سے بھی اسی طرح مروی ہے۔ اور سیدنا عمر رضی اللہ عنہ نے درے کی جو مار ایک شخص کو ہوئی تھی اس کا بدلہ لینے کے لیے کہا: اور سیدنا علی رضی اللہ عنہ نے تین کوڑوں کا قصاص لینے کا حکم دیا۔ جو علماء ان معاملات میں قصاص اور بدلے کے قائل نہیں ان کا کہنا ہے کہ ان بزرگوں نے بطور تعزیر بدلہ دلوایا ہے۔ قاضی شریح نے کوڑے اور خراش لگانے کی سزا دی تھی۔ سیدنا عبداللہ بن زبیر رضی اللہ عنہ نے ہڈی کو اپنی جگہ سے ہلا دینے والے زخم کا بدلہ دلوایا اور ابوبکر بن محمد بن عمرو بن حزم نے ران توڑنے کا بدلہ دلوایا۔ جو علماء ان معاملات میں بدلہ دیے جانے کے قائل ہیں ان حضرات کی دلیل وہ روایت ہے جو جناب عبدالرحمان بن ابی لیلیٰ سیدنا اسید بن حضیر رضی اللہ عنہ سے روایت کرتے ہیں (اور یہ انصار میں سے تھے) یہ ایک دفعہ اپنی قوم سے باتیں کر رہے تھے، مزاحیہ آدمی تھے اور انہیں ہنسا رہے تھے کہ نبی کریم صلی اللہ علیہ وسلم نے ان کی کوکھ میں ایک لکڑی چھودی۔ تو انہوں نے کہا: مجھے بدلہ دیجئے! آپ صلی اللہ علیہ وسلم نے فرمایا: ’’لے لو۔‘‘ انہوں نے کہا: آپ پر تو قمیص ہے اور مجھ پر قمیص نہیں تھی۔ تو نبی کریم صلی اللہ علیہ وسلم نے اپنی قمیص اوپر کر دی تو اسید نے آپ صلی اللہ علیہ وسلم کو اپنے بازؤں میں لے لیا اور آپ کے پہلو پر بوسے دینے لگے اور کہنے لگے: اے اللہ کے رسول! میری یہی نیت تھی۔ (صحیح، ابوداود: ۵۲۲۴) (أَصْبِرْنِي) مجھے بدلہ دیجیے، (اصْطَبِرْ) تو بدلہ لے لے۔ سیدنا ابوسعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم مال (غنیمت) کی تقسیم فرما رہے تھے کہ ایک شخص آیا اور آپ کے اوپر جھک گیا، آپ کے پاس ایک چھڑی تھی۔ آپ نے وہ چھڑی اسے چھبو دی جس سے اس کا مہرہ زخمی ہو گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’آؤ اور اپنا بدلہ لے لے۔‘‘ اس شخص نے کہا: اے اللہ کے رسول! میں نے آپ کو معاف کیا۔ (ضعیف، نسائی: ۴۷۷۳) سیدنا عمر رضی اللہ عنہ نے کہا: میں نے اپنے کارندوں اور حکومتی عمال کو اس لیے نہیں بھیجا کہ وہ تمہاری گردنیں ماریں اور مال ہتھیا لیں۔ جسے اس قسم کا معاملہ پیش آئے وہ اسے مجھ تک پہنچائے میں اسے قصاص لے کر دوں گا۔ اس پر سیدنا عمرو بن عاص رضی اللہ عنہ نے کہا: اگر کوئی شخص اپنے زیر دست افراد کو ادب سکھانے کیلئے کچھ کہے تو کیا آپ اس کا بھی قصاص لیں گے؟ سیدنا عمر رضی اللہ عنہ نے کہا: اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! میں ضرور اس سے بھی قصاص لوں گا۔ میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم اپنی ذات اقدس میں قصاص دلاتے تھے۔ (اس حدیث کا مرفوع حصہ سنن نسائی: ۴۷۷۷ میں ہے اور وہ ضعیف ہے)"}],[2534,"سیدنا ابو جحیفہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے سیدنا علی رضی اللہ عنہ سے سوال کیا آپ حضرات (اہل بیت) کے پاس قرآن کے پاس اور بھی کوئی چیز ہے؟ انہوں نے کہا: نہیں، اس ذات کی قسم جس نے دانے کو (زمین) چیر کر (نکالا) اور جس نے روح کو پیدا کیا! البتہ سمجھ ایک دوسری چیز ہے، جو اللہ کسی بندے کو قرآن میں عطا فرمائے یا جو اس صحیفے میں ہے، میں نے پوچھا: اس صحیفے میں کیا لکھا ہے؟ انہوں نے بتایا کہ دیت کے احکام اور قیدی کا چھڑانا اور مسلمان کا کافر کے بدلے میں نہ قتل کرنا۔","",{"k":"أخرجه البخارى: 111، 3047، 6903"}],[2535,"سیدنا علی رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تمام اہل اسلام کے خون برابر ہیں ان کے ذمے اور امان کا ان ادنیٰ سے ادنیٰ آدمی بھی پابند ہے۔ اسلام کے مرکز سے دور رہنے والا شخص بھی مال غنیمت لشکر میں جمع کروائے گا۔ اور وہ لشکر اپنے علاوہ کے مقابلے میں ایک ہاتھ ہیں (ایک دوسرے کی مدد کرنے کے پابند ہیں) کسی مسلمان کو کسی کافر کے بدلے میں اور کسی امان والے کو اس کے ایام امان میں قتل نہ کیا جائے۔‘‘","",{"k":"أخرجه ابوداود: 4530، والنسائى: 4760"}],[2536,"جناب عمرو بن شعیب اپنے والد سے، وہ اپنے دادا سے روایت کرتے ہیں کہ فتح مکہ والے دن رسول اللہ صلی اللہ علیہ وسلم بیت اللہ کی سیڑھیوں پر چڑھے اور فرمایا: ’’سب تعریفات اس اللہ کے لیے ہیں جس نے اپنا وعدہ (فتح والا) سچا کر دکھایا اور اپنے بندے کی مدد کی اور تمام لشکروں کو اکیلے ہی شکست دی۔‘‘ یہ مکہ اللہ تعالیٰ کے حرام قرار دینے سے حرمت والا ہے، اس میں سے کوئی کانٹا نہ اکھیڑا جائے، اس میں موجود شکار کو نہ بھگایا جائے اور اس کا لقطہ (گری ہوئی چیز) نہ اٹھایا جائے سوائے اس کے جس نے اس کا اعلان کرنا ہو۔‘‘ سیدنا عباس رضی اللہ عنہ نے کہا: اے اللہ کے رسول! اذخر گھاس کی اجازت دے دیجئے: بلاشبہ اس کی گھروں (میں چھت ڈالنے) اور مردوں (کو دفنانے کیلئے) ضرورت رہتی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اذخر گھاس کاٹنے کی اجازت ہے، مسلمان اپنے علاوہ کے مقابلے میں ایک ہاتھ ہیں (ایک دوسرے کی مدد کرنے کے پابند ہیں) ان کے خون برابر ہیں۔ ان کے ذمے کا ادنیٰ سے ادنیٰ آدمی بھی پابند ہے۔ مسلمانوں کا بعید ترین فرد بھی امان دے سکتا ہے، کسی مسلمان کو کافر کے بدلے میں قتل نہ کیا جائے اور نہ کسی امان والے کو اس کی مدت امان کے دوران مارا جائے اور دو الگ الگ دینوں والے ایک دوسرے کے وارث نہیں ہو سکتے۔‘‘","",{"k":"صحيح: أخرجه ابوداود مختصرا: 2911، 4531","e":"(الْمُسْلِمُونَ يَدٌ عَلَى مَنْ سِوَاهُمْ) ’’مسلمان دوسروں کے مقابلہ میں ایک ہاتھ ہیں۔‘‘ یعنی اسلام کے علاوہ کسی بھی دین کے حاملین سے ضرب و پیکار کی نوبت آجائے تو مسلمان آپس میں ایک دوسرے کی معاونت کرتے اور اتحادی بن جاتے ہیں (خواہ ان کے علاقے اور وطن جدا جدا ہی کیوں نہ ہوں) اور جب انہیں میدان جہاد سے جانے کی صورت میں بلایا جائے تو ان پر لبیک کہنا لازمی ہے اور سستی، کرنے اور پیچھے رہ جانے کی قطعاً کوئی گنجائش نہیں۔ (تَتَكَافَأُ دِمَاؤُهُمْ) ’’ان کے خون برابر ہیں۔‘‘ مراد یہ ہے کہ قصاص میں سب مسلمانوں کے خون برابر ہیں۔ ایک کم تر خاندان کے فرد کا خون بہا ایک اونچے اور اعلیٰ خاندان کے فرد سے لیا جائے گا، چھوٹے کے مقابلے میں بڑے، جاہل کے بدلے عالم اور عورت کے بدلے میں مرد کو قصاصاً مارا جائے گا، جاہلیت کے اصول کے برعکس اگر مقتول اونچے حسب ونسب والا یا عالم ہو جبکہ قاتل معمولی خاندان والا یا جاہل ہو تو بطور قصاص قاتل کا ہی سر قلم کیا جائے گا کسی دوسرے کا نہیں جبکہ اسلام سے پہلے یہ اصول کارفرما تھا کہ مقتول اگر کسی اعلیٰ خاندان کا فرد ہوتا تو قصاص میں کمین خاندان کے بہت سارے افراد کو موت کے گھاٹ اتار دیا جاتا اور ذرا دریغ نہ کیا جاتا۔ (وَيَسْعَى بِذِمَّتِهِمْ أَدْنَاهُمْ) ’’ان کے ذمے کا ادنیٰ سے ادنی آدمی بھی پابند ہے‘‘، یعنی اگر مسلمانوں میں سے کوئی فرد کسی کافر کو امان فراہم کر دے تو اس کافر کا خون تمام مسلمانوں پر حرام قرار پائے گا خواہ پناہ دینے والا شخص ادنیٰ اور کم تر حیثیت کا مالک ہی کیوں نہ ہو مثلاً غلام ہو، خاتون ہو یا کسی خاندان کا ذاتی نوکر اور خصوصی خدمت گزار ہو یا کسی بھی نوعیت کا معمولی شخص ہو تو اس کی دی ہوئی امان کو توڑا نہیں جائے گا۔ (وَيُجِيرُ عَلَيْهِمْ أَقْصَاهُمْ) ’’مسلمانوں کا بعید ترین فرد بھی امان دے سکتا ہے‘‘ ان الفاظ کا مفہوم یہ ہے کہ مسلم امت کا وہ فرد ہو جو بلاد کفر سے بہت دور سکونت پذیر ہے اگر کسی کافر کو پروانہ امن لکھ دیتا ہے تو کسی دوسرے مسلمان کے لیے اس پروانہ امن کی خلاف ورزی شرعاً جائز نہیں خواہ وہ پروانہ امن کے حامل کافر شخص کے پڑوس اور ہمسائیگی ہی میں رہائش پذیر کیوں نہ ہو۔ بعض روایات میں (يَرُدُّ مُشِدُّهُمْ عَلَى مُضْعِفِهِمْ، وَمُتَسَرِّيهِمْ عَلَى قَاعِدِهِمْ)...... ’’اور ان کا تنومند اور قوی رفتار اپنے ضعیف اور سست رفتار کو بھی ساتھ ملائے (مال غنیمت میں اس کو شریک کرے) اور چھوٹے دستے میں جانے والا بڑے لشکر میں رہ جانے والوں کو بھی شریک سمجھے! المشد سے مراد تنومند اور قوی شخص ہے اور المضعف سے مراد وہ شخص جس کے چوپائے لاغر اور کمزور ہو کر سست رفتار ہو گئے ہوں۔ بعض احادیث میں مذکور ہے کہ المضعف سے مراد کسی دستے کا امیر اور ذمہ دار ہے، مطلب یہ ہے کہ لشکر کے کچھ افراد جو خود کمزور اور لاغر ہوں یا جن کی سواریاں دبلی پتلی ہوں اور تیز چلنے میں لشکر کا ساتھ نہ دے سکتی ہوں اور دستے کا امیر ان کی دلجوئی کے لیے ان کے ہم رکاب رہے اگر چہ ایسے لوگ جہاد میں کوئی بلند کردار ادا نہ کرسکیں لیکن ان کو مال غنیمت میں ضرور شریک کیا جائے گا۔ (الْمُتَسَرِّي) سے مراد لشکر میں شمولیت اختیار کرنے والا فرد ہے۔ حدیث مبارکہ کے اس آخری جملے کا مطلب یہ ہے کہ جہاد میں شریک ہونے والے تمام مجاہد مال غنیمت میں حصے دار ہوں گے حتی کہ ایک چھوٹا دستہ، بڑے لشکر سے الگ ہو کر کوئی جہادی معرکہ سرکرے اور وہاں سے مال غنیمت حاصل کرے تو اس سے بڑے لشکر والے بھی، جو اپنے امیر کے ساتھ بیٹھے رہے، شریک ہوں گے۔ حدیث مبارکہ کے الفاظ (وَيَرُدُّ عَلَيْهِمْ أَقْصَاهُمْ) کا بھی یہی مفہوم ہے۔ یاد رہے! جو لوگ اپنے علاقے ہی میں اقامت گزیں رہے ہوں اور جہاد کے لیے بالکل نہ نکلے ہوں انہیں مال غنیمت کی تقسیم میں شریک نہیں کیا جائے گا۔ حدیث ہذا میں اس بات کی دلیل ہے کہ مسلمان کو کافر کے بدلے قتل نہیں کیا جائے گا، خواہ کافر ذمی ہو اور مستقل اور غیر محدود مدت کے لیے امن کا معاہدہ رکھتا ہو یا قلیل اور تھوڑی مدت کے لیے پروانہ امن لے کر اسلامی حکومت میں چل پھر رہا ہو۔ صحابہ کرام رضی اللہ عنہم، تابعین رحمہم اللہ اور بعد کے ادوار کے علماء کی ایک کثیر تعداد یہ موقف رکھتی ہے، صحابہ میں سے سیدنا عمر، سیدنا عثمان، سیدنا علی اور زید بن ثابت رضی اللہ عنہم کا یہ موقف ہے اور تابعین میں سے جناب عطاء، عکرمہ، حسن بصری اور عمر بن عبدالعزیز رحمہم اللہ اس کے قائل ہیں۔ آئمہ میں سے امام مالک، سفیان ثوری، ابن شبرمہ، اوزاعی، شافعی، احمد اور اسحاق رحمہم اللہ اس طرف گئے ہیں۔ علماء کی ایک جماعت کا یہ موقف بھی ہے کہ مسلمان کو ذمی (مسلمان ملک کے غیر مسلم باشندے ’’ذمی‘‘ کہلاتے ہیں) کے بدلے قتل کیا جائے گا۔ امام شعبی رحمہ اللہ، نخعی اور اہل رائے یہی موقف رکھتے ہیں، ان حضرات نے حدیث مبارکہ کے الفاظ (لَا يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ) ’’کسی مومن کو کافر کے بدلے قتل نہ کیا جائے‘‘ کا یہ مطلب بیان کیا ہے کہ یہاں کافر سے مراد حربی اور دار کفر کا رہائشی کافر ہے معاہد اور مستامن نہیں۔ ان حضرات کی دلیل یہ ہے کہ حدیث مبارکہ کے الفاظ (وَلَا ذُو عَهْدٍ فِي عَهْدِهِ) کا عطف سابقہ جملے پر ہے اور حدیث کا معنی یہ ہے کہ کسی مسلمان کو کافر کے بدلے قتل نہیں کیا جائے گا اور نہ کسی معاہد (ذمی) کو اپنے عہد میں کافر کے بدلے قتل کیا جائے گا۔ البتہ معاہد (ذمی) معاہد کے بدلے میں قتل کیا جائے گا، حربی کافر کے بدلے میں نہیں البتہ اگر کوئی مسلمان کسی معاہد اور ذمی کو قتل کر دے تو ذمی کے بدلے مسلمان کو قتل کیا جائے گا۔ ان حضرات کی دلیل یہ منقطع روایت بھی ہے جو عبدالرحمن بن البیلمانی سے مروی ہے کہ مسلمانوں میں سے ایک شخص نے اہل ذمہ میں سے ایک شخص کو قتل کر دیا، اس مسئلہ کو جناب رسول اللہ صلی اللہ علیہ وسلم کے حضور پیش کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’میں اپنے ذمہ اور عہد کو پورا کرنے والے کا زیادہ حقدار ہوں۔‘‘ پھر آپ صلی اللہ علیہ وسلم نے حکم فرمایا اور اس (مسلمان) شخص کو قتل کر دیا گیا۔ (ضعیف، سنن دار قطنی: ۳/ ۱۳۵، مسند شافعی: ۱۵۶۹) جواباً ان حضرات کی خدمت میں عرض کیا جائے گا کہ حدیث مبارکہ کا جملہ (لَا يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ) ایک مکمل جملہ اور کلام تام ہے، اس کو مابعد جملہ کے ساتھ نتھی کرنے کی ضرورت نہیں بالخصوص جب عطف ڈالنے اور بعد والے جملے کو سابقہ جملہ کے ساتھ ملانے سے شریعت اسلامیہ کا ایک ثابت شدہ حکم باطل ٹھہرتا ہو اور حدیث مبارکہ کے الفاظ کے ظاہری مفہوم پر زد پڑتی ہو، مزید یہ کہ سیدنا علی رضی اللہ عنہ کے صحیفہ (ورق) کی بات جو ہم تک پہنچی ہے اس میں صرف (لَا يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ) ’’اور کسی مومن کو کافر کے بدلے قتل نہیں کیا جائے گا‘‘ کے الفاظ مذکور ہیں وہاں (وَلَا ذُو عَهْدٍ فِي عَهْدِهِ) کے الفاظ کا کوئی تذکرہ نہیں اور حدیث کے الفاظ میں لفظ کافر عام ہے اور ہر کافر کو شامل ہے، ذمی بھی کافر ہے لہذا اس کے بدلے مسلمان اور مومن کو قتل نہیں کیا جائے گا۔ اس کی تائید نبی کریم صلی اللہ علیہ وسلم کے ایک اور فرمان سے ہوتی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: «لَا يَرِثُ الْمُسْلِمُ الْكَافِرَ، وَلَا الْكَافِرُ الْمُسْلِمَ» ’’مسلمان کافر کا اور کافر مسلمان کا وارث نہیں بن سکتا۔‘‘ (صحیح بخاری: ۶۷۶۴، صحیح مسلم: ۲۹۰۹) اس مسئلہ میں ذمی، مستامن اور حربی سب کافر برابر ہیں تو مسئلہ زیر بحث میں بھی اسی طرح ہے۔","f":"اس حدیث میں صرف یہ ہے کہ ذمی کو عہد توڑنے سے پہلے قتل نہیں کیا جائے گا۔ یہ وضاحت نہیں کہ مسلمان کو ذمی کے بدلے قتل کر دیا جائے گا اور (ع، س) ہی اس پر قابل حجت دلیل موجود ہے لہذا یہی معلوم ہوتا ہے کہ ذمی کے بدلے بھی مسلمان کو قتل نہیں کیا جائے گا۔ (وَلَا ذُو عَهْدٍ فِي عَهْدِهِ) ’’اور کسی امان والے کو اس کے ایام امان میں قتل نہ کیا جائے‘‘، مطلب یہ ہے کہ کسی معاہد کافر کو قتل کرنے میں پہل نہ کی جائے (مسلمان اسے دھوکے سے قتل نہ کرے) جب تک وہ اپنے ذمے اور عہد کی پاسداری کرتا رہے۔ معاہد کے قتل نہ کرنے کے تذکرے میں ایک خاص فائدہ اور حکمت مضمر ہے اور وہ یہ کہ جب نبی کریم صلی اللہ علیہ وسلم نے کافر کو قتل کرنے پر مسلمان سے بدلے اور قصاص کو ساقط فرمایا تو اس بات کا قوی اندیشہ تھا کہ کافروں کے خون کی بے حرمتی ہونے لگے اور اس فرمان نبوی کو سننے والے ان کے قتل پر دلیر ہو جائیں اور ان کے قتل کے اقدام پر جرات اور بے باکی کے مظاہرے ہونے لگیں۔ اس لیے آپ نے بطور خاص تذکرہ کیا کہ معاہد کا خون محترم ہے کیونکہ اسلامی حکومت ان کے حقوق کی حفاظت کا ذمہ اٹھائے ہوئے ہے۔ آپ کا یہ فرمان کہ کسی امان والے کو اس کے ایام امان میں قتل نہ کیا جائے، طبیعتوں اور اپنے مقاصد کے لیے تاویل باطل کر گزرنے والوں کے لیے قول فیصل کی حیثیت رکھتا ہے اور اس وضاحت کے بعد آئیں، بائیں اور شائیں کی کوئی گنجائش باقی نہیں رہتی۔ واللہ اعلم۔ مزید یہ کہ ابن البیلمانی کی حدیث منقطع ہے جس سے دلیل قائم نہیں ہو سکتی اور اس میں بیان شدہ بات خطا پر مبنی ہے اور وہ یہ کہ قاتل عمرو بن امیہ ضمری تھے جو کہ نبی کریم صلی اللہ علیہ وسلم کی وفات کے بعد تک زندہ رہے۔ اگر یہ حدیث متصل ثابت ہو جائے تو بھی اس پر عمل متروک ہے کیونکہ مروی ہے کہ قتل ہونے والا کافر قاصد اور سفیر تھا۔ اس صورت میں اس کی حیثیت مستأمن (پروانہ امن لے کر آنے والے) کی ہے اور اس بات پر اتفاق ہے کہ مسلمان کو مستأمن کافر کے بدلے میں قتل نہیں کیا جائے گا یا پھر یہ مسئلہ منسوخ قرار پائے گا کیونکہ اس کا وقوع فتح مکہ سے قبل ہوا تھا اور نبی کریم صلی اللہ علیہ وسلم نے فتح مکہ والے دن فرمایا: (لَا يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ) ’’کسی مومن کو کافر کے بدلے قتل نہ کیا جائے‘‘ تو اس فرمان نبوی کی روشنی میں پہلا حکم منسوخ قرار پاتا ہے۔"}],[2537,"سیدنا سمرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے غلام کو قتل کرے گا ہم اسے قتل کریں گے اور جو اپنے غلام کی ناک کاٹے گا ہم اس کی ناک کاٹیں گے اور جس نے اپنے غلام کو خصی کیا ہم اسے خصی کر دیں گے۔‘‘","",{"k":"ضعيف: أخرجه ابوداود: 4515، والترمذى: 1414، وابن ماجه: 2663، والنسائى: 4738","e":"اہل علم کا اس بارے میں اختلاف ہے کہ اگر کوئی آزاد شخص کسی غلام کو قتل کر دے یا اس کے اعضاء کاٹ دے تو کیا اس پر قصاص واجب ہے یا نہیں؟ اکثر فقہاء کا خیال ہے کہ اس پر قصاص نہیں ہے۔ یہ موقف سیدنا ابوبکر، عمر فاروق اور ابن زبیر رضی اللہ عنہم سے مروی ہے، نیز سیدنا حسن بصری، عطاء، عکرمہ، عمر بن عبدالعزیز کا یہی قول ہے۔ امام مالک، شافعی، احمد اور اسحاق رحمہم اللہ اسی طرف گئے ہیں جبکہ اہل علم کی ایک جماعت کا خیال ہے کہ آزاد کو غلام کے بدلے قتل کیا جائے گا خواہ اس نے اپنے غلام کو قتل کیا ہو یا کسی دوسرے کے غلام کو۔ یہ قول ابراہیم نخعی اور سفیان ثوری رحمہما اللہ کا ہے۔ اہل علم کی ایک جماعت کا خیال ہے کہ اگر کوئی مالک اپنے غلام کو قتل کر دے تو اس سے قصاص نہیں لیا جائے گا اور اگر کسی دوسرے کے غلام کو مار دے تو اس سے قصاص لیا جائے گا، جناب سعید بن مسیب، شعبی اور قتادہ اسی کے قائل ہیں، اہل رائے بھی یہی موقف رکھتے ہیں۔ جناب سفیان سے بھی انہی کے قول کی طرح مروی ہے۔ جناب قتادہ سے مروی ہے کہ جناب حسن بصری رحمہ اللہ مندرجہ صدر حدیث مبارکہ بھول گئے تھے اور اس موقف کے قائل ہو گئے تھے کہ آزاد کو غلام کے بدلے قتل نہیں کیا جائے گا اور جو حضرات اس مسئلہ میں قصاص کے قائل نہیں ان کے نزدیک یہ حدیث مبارکہ زجر و توبیخ اور تنبیہ پر مبنی ہے نہ کہ قصاص لینے کے وجوب پر اور بعض نے اس حدیث کی یہ تاویل کی ہے کہ جس کی ملکیت میں غلام تھا پھر اس نے اس کو آزاد کر دیا اور پھر قتل کر دینے کا معاملہ پیش آیا (حدیث میں سابقہ ملکیت کا تذکرہ ہے) ہو تو ہم اسے قتل کر دیں گے۔ ویسے اہل علم کا اس بارے میں کوئی اختلاف نہیں کہ اگر آقا اپنے آزاد کردہ غلام کو قتل کر دے تو اس پر قصاص واجب ہے۔ اکثر اہل علم کا یہ موقف ہے کہ آزاد کے اعضائے بدن کو غلام کے قصاص میں نہیں کاٹا جائے گا اور اہل علم کے اس اتفاق سے یہ بات ثابت ہوئی کہ یہ حدیث مبارکہ زجر و توبیخ اور ڈانٹ ڈپٹ پر مبنی ہے یا پھر یہ روایت منسوخ ہے۔ جب غلام کے بدلے آزاد کا کوئی عضو نہیں کاٹا جا سکتا اور اس بات پر اہل علم کا اتفاق ہے تو پھر غلام کے بدلے آزاد کو قتل کیونکر کیا جاسکتا ہے باقی رہی حدیث مبارکہ تو وہ زجر و توبیخ پر مبنی ہے۔ اعضاء کاٹ ڈالنے کی صورت میں قصاص لینے کے متعلق اہل علم کا اختلاف ہے۔ ایک جماعت کا خیال ہے کہ جس طرح جانوں اور نفوس کے متعلق قصاص کے اصول وضوابط ہیں اسی طرح جسم کے اعضاء میں بھی انہیں اصول وضوابط کا اجراء ہو گا بشرطیکہ ظالم اور مظلوم کا وہ عضو جس کا قصاص لینا مقصود ہے صحیح سلامت اور تندرست ہو مثلاً عورت کے بدلے مرد کے اور مرد کے بدلے عورت کے اعضاء کاٹے جائیں گے لیکن ذمی (کافر) کے بدلے مسلمان کے اور غلام کے بدلے آزاد کے اعضاء کو نہیں کاٹا جائے گا جیسا کہ ذمی کے بدلے مسلمان کو اور غلام کے بدلے آزاد کو قتل نہیں کیا جاتا، البتہ مسلمان کے بدلے ذمی کے اور آزاد کے بدلے غلام کے اور غلام کے غلام کے بدلے قصاصاً اعضاء کاٹے جائیں گے خواہ غلاموں کی قیمتیں آپس میں متفاوت ہی کیوں نہ ہوں جیسا کہ ان حضرات کا ایک دوسرے کے بدلے قصاصاً قتل کردینا جائز ہے، امام شافعی رحمہ اللہ کا یہی قول ہے اور سیدنا عمر رضی اللہ عنہ نے کہا کہ عورت سے مرد کے قتل مثل عمد یا اس سے کم دوسرے زخموں کا قصاص لیا جائے، یہی قول عمر بن عبد العزیز، ابراہیم، ابوالزناد کا اپنے اساتذہ سے منقول ہے اور ربیع کی بہن نے نبی کریم صلی اللہ علیہ وسلم کے زمانہ میں ایک شخص کو زخمی کر دیا تھا تو آنحضرت صلی اللہ علیہ وسلم نے قصاص کا فیصلہ فرمایا تھا۔ (صحیح مسلم: ۱۶۷۵) اہل علم کی ایک جماعت کا موقف ہے کہ اعضائے جسم کا قصاص صرف اور صرف دو آزاد مردوں یا دو آزاد عورتوں کے مابین ہی جاری ہوگا باقی کسی صورت میں قصاص نہیں لیا جائے گا، مثلاً مذکر اور مونث کے درمیان، دو غلاموں میں، آزاد اور غلام کے مابین قصاص جاری نہیں ہوگا۔ یہ موقف اہل رائے کا ہے۔ امام ابن شہاب زہری رحمہ اللہ نے کہا: آزاد اور غلام کے درمیان کسی قسم کے زخموں میں قصاص جاری نہیں ہوگا الا یہ کہ کوئی غلام کسی آزاد شخص کو جان بوجھ کر قتل کر دے تو پھر اسے قصاص میں قتل کیا جائے گا۔ امام حکم نے کہا: غلام سے دوسرے غلام کو لگائے ہوئے زخموں کا قصاص نہیں لیا جائے گا خواہ وہ زخم عمد لگائے گئے ہوں یا بصورت خطا البتہ قتل عمد کی صورت میں ضرور قصاص لیا جائے گا، امام حاکم نے یہی موقف جناب ابراہیم نخعی، شعبی اور سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے بھی ذکر کیا ہے۔ جب ظالم اور مظلوم کے اعضاء صحت اور تندرستی میں متفاوت ہوں مثلاً مظلوم کا ہاتھ مفلوج اور شل ہو جبکہ مجرم کا ہاتھ تندرست وتوانا ہو تو ایسی صورت میں بالاتفاق بدلہ نہیں لیا جائے گا (بلکہ معاوضہ دیا جائے گا) اور اگر مجرم کا ہاتھ شل ہو اور جس شخص کا ہاتھ کاٹا گیا ہے وہ صحیح سلامت تھا تو مظلوم کو بالاتفاق اس بات کا اختیار ہے، چاہے تو ظالم کے شل ہاتھ کا قصاص لے لے اور اس صورت میں اسے کوئی معاوضہ وغیرہ نہیں ملے گا اور اگر چاہے تو قصاص نہ لے اور اپنے ہاتھ کی دیت وصول کر لے۔ اگر مظلوم کے ہاتھ کی ایک انگلی کم ہو اور کاٹنے والے شخص کا ہاتھ پورا یعنی پانچ انگلیوں پر مشتمل ہو تو قصاص میں اس کا ہاتھ نہیں کاٹا جائے گا، ہاں البتہ جس شخص کا ہاتھ کاٹا گیا ہے اسے چار انگلیاں کاٹنے کا اختیار حاصل ہے اور اگر معاملہ اس کے برعکس ہو یعنی ہاتھ کاٹنے والے شخص کے ہاتھ میں ایک انگلی کا نقص ہو اور مقطوع (جس کا ہاتھ کاٹا گیا ہے) شخص کا ہاتھ مکمل ہو تو وہ کاٹنے والے کا ہاتھ کاٹ سکتا ہے اور ایک انگلی کی دیت وصول کر لے جو اس کے ہاتھ میں کم ہے، یہ امام شافعی رحمہ اللہ کا فتویٰ ہے۔ امام ابو حنیفہ رحمہ اللہ نے کہا: جب مظلوم، ظالم کے ہاتھ کو کاٹنے پر راضی ہو جائے جس میں ایک انگلی کم ہے تو اسے دیت نہیں دی جائے گی جیسے اگر ہاتھ کاٹنے والے کا ہاتھ شل ہو اور مظلوم اس ہاتھ کے کاٹنے پر راضی ہو جائے تو اسے مزید کچھ نہیں دیا جائے گا۔ جو علماء غلاموں کے درمیان اعضاء وغیرہ کے قصاص کے قائل نہیں، ان کی دلیل وہ حدیث مبارکہ ہے جو سیدنا عمران بن حصین رضی اللہ عنہ سے مروی ہے کہ فقیر لوگوں کے غلام نے، مالدار لوگوں کے غلام کا کان کاٹ دیا تو کان کاٹنے والے غلام کے مالک نبی کریم صلی اللہ علیہ وسلم کے پاس آئے اور عرض کی: اے اللہ کے رسول! ہم مفلس و قلاش لوگ ہیں۔ تو آپ نے اس کے اوپر کوئی تاوان نہ ڈالا۔ امام بغوی رحمہ اللہ نے کہا: اس حدیث کا مفہوم یہ ہے کہ دونوں غلام آزاد تھے اور جرم بطور خطا ہوا تھا یا وہ دونوں غلام نابالغ تھے اور قتل خطا کی دیت عاقلہ (برادری کے افراد) پر آئے گی، اگر وہ مالدار ہوں اور اگر وہ نادار ہوں تو ان پر کوئی دیت نہیں اگر مجرم غلام ہوتا تو دیت کا بوجھ اس کی گردن پر ہوتا اور اس کے مالکوں کی غربت کی بنا پر مظلوم کا حق ضائع نہ ہوتا۔ اگر غلام غلام پر زیادتی کرے یا کسی آزاد پر بطور خطا زیادتی کر بیٹھے یا کسی آزاد پر عمداً غلطی کرے ان کے مطابق جو قصاص کو واجب نہیں سمجھتے۔ یا وہ مال کو برباد کر دے تو دیت غلام ہی کے ذمہ ہوگی جس نے جرم کیا ہے مالک کو اختیار ہے اگر چاہے تو اس کو بکنے کیلئے پیش کر دے اور اگر چاہے تو اپنے پاس سے فدیہ دے دے، اگر وہ دیت دینا پسند کرے تو مجرم غلام کی قیمت یا اس کے جرم کی دیت میں سے کم قیمت والی چیز اس کے ذمے آئے گی اور اگر وہ اسے بیچنے کے لیے پیش کرتا ہے تو اسے بیچ دیا جائے گا۔ اگر تو اس کی قیمت جرم کی دیت کے برابر ہو تو مظلوم کے ولی کے حوالے کر دی جائے گی اور اگر بڑھ جائے تو غلام کے مالک کو مل جائے گی اور اگر کم ہو جائے تو مظلوم کو یہی ملے گا۔ اگر اس کا مالک اسے آزاد کر دے تو وہ آزاد ہوگا اور قیمت یا جرم کے تاوان میں سے جو چیز ہلکی ہوگی مالک کے ذمے آئے گی۔ امام شعبی کہتے ہیں: اگر کوئی غلام قتل خطا کرتا ہے اور اس کا مالک اسے آزاد کر دیتا ہے تو دیت مالک کے ذمے آئے گی مکاتب غلام اور ام ولد کو عبد قن کے عوض قتل کیا جائے گا۔ اور عبد قن کو ان دونوں کے بدلے قتل کیا جائے گا (کیونکہ یہ دونوں غلام ہی ہے)۔ جناب عمرو بن شعیب اپنے پردادا محترم سے روایت کرتے ہیں اور وہ بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے بیان فرمایا: ’’بیٹے کے بدلے میں باپ کو قتل نہ کیا جائے۔‘‘ (صحیح، ترمذی: ۱۴۰۰، ابن ماجہ: ۲۶۶۲) بعض راویوں نے اس حدیث کو عمرو بن شعیب عن ابیہ عن جدہ عن عمر بن الخطاب کی سند سے بیان کیا ہے اور بعض نے عن سراقہ بن مالک کی سند سے اس حدیث کی سند میں اگر چہ اضطراب ہے (جس کی بنا پر یہ روایت ضعیف ہے) لیکن اس کے باوجود قابل عمل اور قابل حجت ہے اور اسی پر تمام اہل علم کا عمل ہے۔ ان کا کہنا ہے والدین میں سے کسی ایک کو اولاد کے بدلے میں قتل نہیں کیا جائے گا۔ اسی طرح والدین کو اولاد پر الزام اور تہمت لگانے کی صورت میں حد قذف نہیں لگائی جائے گی۔ اس کے برعکس اولاد کو ماں باپ کے بدلے میں قتل کیا جائے اور الزام تراشی کی صورت میں حد قذف لگائی جائے گی سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بیٹے کے بدلے میں باپ سے قصاص نہ لیا جائے۔‘‘ (حسن، ترمذی: ۱۴۰۱، ابن ماجہ: ۲۶۶۱)","f":"عبد قن اس غلام کو کہتے ہیں جس کے والدین بھی غلام ہوں۔ ماں باپ کے ہاتھ سے اگر اولاد قتل ہو جائے تو ماں باپ کو قصاص میں قتل نہیں کیا جائے گا، البتہ دوسری مناسب سزا ضروری ہے۔"}],[2538,"سیدنا ابو رمثہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے کہا: میں نبی اکرم صلی اللہ علیہ وسلم کے پاس اپنے والد کے ساتھ حاضر ہوا، میرے والد نے رسول اللہ صلی اللہ علیہ وسلم کی کمر پر خاتم نبوت کو دیکھا تو کہا: مجھے اجازت دیجئے! میں آپ کی کمر پر موجود چیز کا علاج کروں، میں طبیب ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: تو نرمی اور مہربانی کرنے والا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے دریافت فرمایا: ’’یہ تیرے ساتھ کون ہے؟‘‘ انہوں نے کہا: میں گواہی دیتا ہوں کہ یہ میرا بیٹا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: ’’خبردار! یہ تیرے جرم کا ذمہ دار نہیں اور تو اس کے جرم کا ذمہ دار نہیں۔‘‘","",{"k":"اسناده صحيح علي شرط مسلم: أخرجه الامام احمد في المسند: 17493","e":"مسند احمد بن حنبل میں اسی سند کے ساتھ مروی ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تو شفقت اور مہربانی کرنے والا اور اللہ تعالیٰ طبیب ہے (بیماری کو جڑ سے ختم کرنے والا ہے)۔‘‘ (أَنْتَ رَفِيقٌ) ’’تو مہربان اور ترس کھانے والا ہے‘‘ مطلب یہ ہے کہ تو مریض کے حال پر ترس کھانے والا ہے کہ کہیں اس بیماری کی لپیٹ میں اس کا سارا جسم ہی نہ آ جائے اور اس مرض کے جراثیم پورے بدن میں سرایت نہ کر جائیں اس لیے تو مریض کے مناسب حال دوائی دیتا ہے تا کہ مرض کا قلع قمع ہو۔ الطبیب سے مراد بیماری اور علاج کی حقیقتوں سے واقف اللہ تعالیٰ ہی کی ذات ہے، وہی صحت و تندرستی عطا کرنے پر قادر ہے۔ اللہ واحد قہار کے سوا کسی میں مریض کو شفایاب کرنے کی طاقت نہیں۔ شفا طلب کرتے وقت ان ناموں سے پکارنا مثلاً یوں کہنا: اللَّهُمَّ أَنْتَ الْمُصِحُّ وَالْمُمَرِّضُ وَالْمُدَاوِي وَالطَّبِيبُ وغیرہ کے الفاظ سے دعا کرنا، اسی طرح یوں کہنا اے طبیب ایسے کر دے جیسا کہ یا حلیم اور یا کریم کہا جاتا ہے، تو یہ آداب دعا کے منافی ہوگا۔","f":"کیونکہ یہ الفاظ اسماء اللہ الحسنیٰ میں شامل نہیں۔ (ع، س)"}],[2539,"جناب سعید بن مسیب رحمہ اللہ نے بیان کیا کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے ایک جماعت یعنی پانچ یا سات افراد کو ایک آدمی کے بدلے میں قتل کیا، جنہوں نے اس شخص کو دھوکے سے قتل کر دیا تھا، اور سیدنا عمر بن خطاب رضی اللہ عنہ نے کہا: اگر تمام اہل صنعاء اس کے خلاف تعاون کرتے تو میں سب کو قتل کر دیتا۔","",{"k":"أخرجه البخارى: 6896، ومسلم:","e":"جناب مغیرہ بن حکیم اپنے والد محترم سے بیان کرتے ہیں کہ ایک مرتبہ چار افراد نے مل کر ایک بچے کو قتل کر دیا تھا، تب بھی سیدنا عمر رضی اللہ عنہ نے اسی طرح کا جملہ ارشاد فرمایا تھا۔ (صحیح بخاری معلقا: کتاب الدیات، باب اذا اصاب قوم من رجل هل يعاقب ام يقتص منهم كلهم) (قَتَلُوهُ غِيلَةً) ’’انہوں نے بہانے سے اس کو قتل کر دیا تھا‘‘ جب کوئی شخص دوسرے کے ساتھ دھوکے سے پیش آئے اور اس کا مال لوٹ لینا چاہتا ہو تو کہا جاتا ہے۔ اِغْتَالَنِي فُلَانٌ. ’’فلاں نے مجھ سے فراڈ کیا۔‘‘ الغِيلَة کے مفہوم میں یہ بھی کہا گیا ہے کہ کسی کو بہلا پھسلا کے ایسے خفیہ مقام میں لے جانا جہاں اس کو قتل کیا جا سکے اور پھر موقع پا کر اس کو قتل کر دیا جائے۔ اہل عرب کا محاورہ ہے کہ لَا تَنْفَعُ حِيلَةٌ مِنْ غِيلَةٍ، حیلہ انسان کو دھوکے سے نہیں بچا سکتا۔ الفتک کا مفہوم یہ ہے کہ ایک شخص اپنے دھیان میں لگا ہوا ہو اور دوسرا شخص اسے غفلت کی حالت میں دبوچ کر قتل کر دے۔ (لَوْ تَمَالَأَ عَلَيْهِ أَهْلُ صَنْعَاءَ) اگر صنعا شہر کے تمام باشندے جمع ہو کر ایک دوسرے کی معاونت کرتے، لفظ تمالا لفظ الملا سے ماخوذ ہے، جس سے مراد کسی قوم کے سربرآوردہ افراد ہیں جن کی ایک ہی بات ہو اور وہ پوری طرح یک زبان ہوں۔ سیدنا علی رضی اللہ عنہ نے کہا تھا: اللہ کی قسم! نہ میں نے عثمان رضی اللہ عنہ کو قتل کیا ہے اور نہ ہی ان کے قتل میں معاونت کی ہے۔ اکثر اہل علم کا یہی موقف ہے کہ اگر ایک شخص کے قتل میں ایک جماعت شریک ہو تو سب کو قصاصاً قتل کر دیا جائے گا۔ سیدنا عمر، سیدنا علی اور سیدنا عبداللہ بن عباس رضی اللہ عنہم کا یہی قول ہے جناب سعید بن مسیب، حسن، عطاء اسی کے قائل ہیں۔ امام مالک، اوزاعی، ثوری، شافعی، احمد، اسحاق رحمہم اللہ اور اہل رائے یہی رائے رکھتے ہیں، امام ربیعہ نے کہا: ایسی صورت میں بالکل قصاص نہیں ہے۔ اہل علم کی ایک جماعت کا خیال ہے کہ مقتول کے ولی کو چاہیے کہ وہ قاتلوں کی ٹیم میں سے کسی ایک کا قتل کے لیے انتخاب کرے اور اسے قتل کر دے اور باقیوں سے شراکت کے اعتبار سے دیت وصول کر لے۔ ایسا موقف سیدنا معاذ اور سیدنا ابن زبیر رضی اللہ عنہما سے مروی ہے، امام زہری اور ابن سیرین رحمہما اللہ بھی اسی کے قائل ہیں۔ اگر لوگوں کی ایک جماعت مل کر کسی شخص کا ہاتھ کاٹ دے یا جسم کا کوئی اور عضو تو اس بارے میں اہل علم کے مابین اختلاف رائے پایا جاتا ہے۔ اہل علم کی ایک جماعت کا موقف ہے کہ شرکائے جرم میں سے ہر ایک کا ہاتھ یا متعلقہ عضو کاٹا جائے گا جس طرح ایک جماعت کو ایک آدمی کے قتل میں شریک ہونے کی بنا پر قتل کر دیا جائے گا۔ اور مطرف نے امام شعبی رحمہ اللہ سے بیان کیا کہ دو آدمیوں نے ایک شخص کے متعلق گواہی دی کہ اس نے چوری کی ہے تو سیدنا علی رضی اللہ عنہ نے اس کا ہاتھ کاٹ دیا۔ اس کے بعد وہی دونوں ایک دوسرے شخص کو لائے اور کہا: ہم سے غلطی ہو گئی تھی (اصل میں چور یہ تھا) تو علی رضی اللہ عنہ نے ان کی شہادت کو باطل قرار دیا اور ان سے پہلے کا (جس کا ہاتھ کاٹ دیا گیا تھا) خون بہا لیا اور کہا کہ اگر مجھے یقین ہوتا کہ تم لوگوں نے جان بوجھ کر ایسا کیا ہے تو میں تم دونوں کا ہاتھ کاٹ دیتا۔ (صحیح بخاری معلقا: کتاب الدیات، باب اذا اصاب قوم من رجل هل يعاقب ام يقتص منهم كلهم) امام شافعی رحمہ اللہ کا بھی یہی موقف ہے۔ ان کا کہنا ہے کہ ایک ہاتھ کے بدلے بہت سارے ہاتھوں کو کاٹا جائے گا لیکن جب بہت سارے ہاتھوں نے ایک ہاتھ کو کاٹنے میں معاونت کی ہو مثلاً کچھ افراد نے مل کر چھری کو پکڑ کر ہاتھ پر رکھا اور کچھ دوسرے لوگوں نے چھری پر بوجھ ڈالا حتی کہ ہاتھ جسم سے کٹ کر الگ ہو گیا تو اس صورت میں سب کے ہاتھ کاٹے جائیں گے۔ اگر کیفیت یہ ہو کہ ایک ہاتھ کاٹتے ہوئے ایک نے ایک طرف سے چھری چلائی اور دوسرے نے دوسری طرف سے حتی کہ دونوں کی چھریاں آپس میں ٹکرا گئیں تو دونوں کے ہاتھ ایک شخص کے ہاتھ کے بدلے میں نہیں کاٹے جائیں گے۔ بعض اہل علم کا یہ موقف بھی ہے کہ ایک عضو کے بدلے میں بہت سارے لوگوں کے اعضاء نہیں کاٹے جائیں گے۔ اہل رائے کا یہی موقف ہے۔ اگر ایک شخص ایک جماعت کو قتل کر دے تو امام شافعی رحمہ اللہ کے نزدیک قاتل کو ان میں سے ایک کے بدلے قتل کر دیا جائے گا اور باقیوں کے ورثا کو قاتل کے ترکہ سے دیت دی جائے گی۔ اسی طرح اگر ایک شخص بہت سارے لوگوں کے ہاتھ کاٹ دے تو ان میں سے ایک کے بدلے میں اس کا ہاتھ کاٹا جائے گا اور باقی افراد کو دیت دی جائے گی۔ مگر اہل رائے کے نزدیک متقولین کی جماعت کے عوض صرف قاتل کو ہی قتل کیا جائے گا اور دیت نہیں لی جائے گی جس طرح اگر جماعت ایک آدمی کے قتل میں شریک ہو تو انہیں قتل کر دیا جاتا ہے (اور دیت وغیرہ کا کوئی مسئلہ نہیں ہوتا) اہل رائے کے نزدیک اگر ایک شخص بہت سارے لوگوں کے ہاتھ کاٹ دیتا ہے تو نتیجتاً اس کا ہاتھ کاٹا جائے گا اور باقی ماندہ ان کے حقوق کو دیت سے پورا کیا جائے گا۔ اگر دو آدمی ایک شخص کے قتل میں شریک ہوں اور ان میں سے ایک خطی (غلطی سے شریک قتل ہو) ہو تو جان بوجھ کر قتل کرنے والے پر بھی کوئی قصاص نہیں، جان کے بدلے میں بالاتفاق یہی موقف ہے (البتہ اعضاء جسم کے متعلق اختلاف ہے) اگر والد کسی دوسرے شخص کی شراکت سے اپنے بیٹے کو قتل کر دے تو امام شافعی رحمہ اللہ کے نزدیک والد پر کوئی قصاص نہیں البتہ دوسرے شخص کو قصاصاً قتل کر دیا جائے گا۔ امام ابو حنیفہ رحمہ اللہ کے نزدیک والد کے ساتھ شریک جرم شخص پر بھی قصاص نہیں جس طرح قتل خطا کے عام شریک پر قصاص نہیں ہے۔ امام شافعی رحمہ اللہ نے یوں فرق کیا ہے کہ باپ ہونے کا شبہ باپ کی ذات تک محدود ہے اور باپ کا وجود شریک کے وجود سے الگ ہے چنانچہ شریک کے حق میں یہ شبہ ثابت نہیں ہوگا جبکہ قتل خطا کا شبہ خود فعل میں پایا جاتا ہے جس کی دلیل یہ ہے کہ اسے کہا ہی قتل خطا جاتا ہے۔ جب قتل خطا کرنے والے اور قتل عمد کرنے والے کا فعل محل قتل میں اکٹھا ہو گیا تو جانبی قصاص کے منع ہونے میں شبہ ثابت ہو گیا۔ اگر ایک شخص کسی کو پکڑ رکھے تا آنکہ دوسرا شخص اس کو قتل کر دے تو پکڑنے والے پر کوئی قصاص نہیں جس طرح اگر کوئی شخص کسی خاتون کو تھامے رکھے اور دوسرا شخص اس کی عزت لوٹ لے تو تھامنے والے پر کوئی حد نہیں۔ امام مالک رحمہ اللہ کا خیال ہے کہ جب کوئی شخص کسی کو پکڑے حالانکہ اسے بخوبی پتہ ہے کہ دوسرا شخص اس کو قتل کر دینا چاہتا ہے تو دونوں کو قصاص میں قتل کیا جائے گا، پکڑنے والے کو بھی اور قتل کرنے والے کو بھی اور اگر کوئی آدمی دوسرے کو پکڑے اور اس کے خیال میں صرف اتنا ہو کہ اگلا شخص صرف اس کو زد و کوب ہی کرے گا اور کچھ نہیں کرے گا (مگر مضروب قتل ہو جائے) تو مارنے والے شخص کو قتل کیا جائے گا اور پکڑنے والے کو سخت ترین سزا دی جائے گی اور اسے ایک سال تک محبوس رکھا جائے گا۔"}],[2540,"سیدنا عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’خبردار! قتل شبہ عمد یعنی جو کوڑے یا لاٹھی کی مار سے ہوا اس کی دیت سو اونٹ مغلظہ ہے، ان میں چالیس اونٹنیاں ایسی ہوں جن کے پیٹوں میں بچے ہوں۔‘‘","",{"k":"حسن: أخرجه ابوداود 4549، والنسائى: 4805، وابن ماجه: 2627","e":"امام بغوی رحمہ اللہ نے کہا: تمام اہل علم کا اس بات پر اتفاق ہے کہ ایک آزاد مسلمان کی دیت سو اونٹ ہے۔ پھر قتل عمد کی صورت میں دیت مغلظہ (ثقیل اور بھاری) ہے جسے قاتل کے مال سے نقد وصول کیا جائے گا اور قتل شبہ عمد کی صورت میں دیت مغلظہ تو ہے مگر اس کی ادائیگی قاتل کی برادری پر ہے اور قسط وار اور تاخیر سے ہے اور قتل خطا (غلطی سے ہو جانے والے قتل) کی دیت مخففہ (ہلکی اور آسان) ہے اور اس کی ادائیگی بھی برادری کے لوگوں پر لازم ہے اور اس کی ادائیگی میں بھی تاخیر روا ہے۔ یاد رہے! دیت میں تغلیظ و تخفیف یعنی بھاری اور آسان ہونے کا تعلق اونٹوں کی عمروں کے ساتھ ہے، ہر صورت میں اونٹ سو ہی ادا کیے جائیں گے مگر عمروں کے تفاوت اور فرق کے ساتھ۔ دیت مغلظہ (شبہ عمد کی دیت) میں اونٹ تین قسموں کے ہوں: تیس اونٹنیاں تین سالہ، تیس اونٹنیاں چار سالہ اور چالیس اونٹنیاں حاملہ جن کے پیٹوں میں بچے ہوں۔ سیدنا عمر بن خطاب، سیدنا زید بن ثابت اور سیدنا ابو موسیٰ رضی اللہ عنہم سے اسی طرح مروی ہے۔ جناب عطاء کا بھی یہی قول ہے نیز امام شافعی رحمہ اللہ کا مذہب بھی یہی ہے، سیدنا ابن مسعود رضی اللہ عنہ نے کہا: دیت مغلظہ میں اونٹ چار طرح کے ہوں، پچیس اونٹنیاں ایک سالہ ہوں، پچیس اونٹنیاں دو سالہ، پچیس اونٹنیاں تین سالہ اور پچیس اونٹنیاں چار سالہ، امام سلیمان بن یسار، زہری، ربیعہ، امام مالک، احمد، اسحاق رحمہم اللہ اور اہل رائے کا یہی موقف ہے۔ قتل خطا کی دیت میں پانچ قسم کے اونٹ دیت میں وصول کیے جائیں گے۔ اکثر اہل علم کی یہی رائے ہے، البتہ ان کی تفصیل میں اختلاف ضرور پایا جاتا ہے۔ ایک قوم کا خیال ہے کہ بیس ایسی اونٹنیاں جن کی عمریں ایک سال ہوں، بیس ایسی اونٹنیاں جن کی عمریں دو سال ہوں، بیس نر اونٹ دو سالہ، بیس نر اونٹ تین سالہ اور بیس چار سالہ، یہ قول جناب عمر بن عبد العزیز، سلیمان بن یسار، زہری، ربیعہ، لیث بن سعد، مالک اور شافعی رحمہم اللہ سے مروی ہے اور بعض لوگوں نے بنو لبون (دو سالہ) کی بجائے بنو مخاض (ایک سالہ نر) کی ادائیگی کی بات کی ہے۔ یہ تفصیل سیدنا ابن مسعود رضی اللہ عنہ، امام احمد، اسحاق اور اہل رائے سے مروی ہے۔ ان حضرات کی دلیل سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے۔ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قتل خطا کی دیت میں فیصلہ فرمایا: بیس اونٹنیاں ایک سالہ، بیس اونٹنیاں دو سالہ، بیس اونٹ مذکر ایک سالہ، بیس اونٹنیاں چار سالہ اور بیس اونٹنیاں تین سالہ۔ (ضعیف، ابوداود: ۴۵۴۵، ترمذی: ۱۳۸۶، ابن ماجہ: ۲۶۳۱، نسائی: ۴۸۱۶) امام شافعی رحمہ اللہ نے اس ترتیب سے اعراض برتا ہے کیونکہ اس حدیث کا راوی خشف بن مالک مجہول ہے اور وہ اس حدیث کے علاوہ معروف نہیں۔ نبی کریم صلی اللہ علیہ وسلم سے مروی ہے کہ آپ نے خیبر کے مقتول کی دیت صدقے کے اونٹوں سے سو اونٹ دی۔ (صحیح بخاری: ۶۸۹۸، صحیح مسلم: ۱۶۶۹) اور زکاة کے اونٹوں میں ایک سالہ نر ذکر وصول نہیں کیا جاتا، بلکہ زکاة میں دو سالہ نر ذکر وصول کیا جاتا ہے، جب اونٹوں کی تعداد پچیس ہو جائے اور ایک سالہ اونٹنی دستیاب نہ ہو۔ اہل علم کی ایک جماعت کا خیال ہے کہ قتل خطا کی دیت کے اونٹ چار طرح کے ہوں: پچیس اونٹنیاں ایک سالہ، پچیس اونٹنیاں دو سالہ، پچیس اونٹنیاں تین سالہ اور پچیس اونٹنیاں چار سالہ، سیدنا علی بن ابی طالب رضی اللہ عنہ، شعبی، نخعی، حسن بصری رحمہم اللہ کا مذہب یہی ہے۔ سیدنا علی رضی اللہ عنہ سے شبہ عمد کی دیت میں اونٹوں کی تین قسمیں مروی ہیں: تینتیس اونٹنیاں تین سالہ، تینتیس اونٹنیاں چار سالہ اور چونتیس اونٹنیاں چھ سے نو سال کے درمیان اور (یہ آخری) سب حاملہ ہوں۔ امام بغوی رحمہ اللہ نے کہا: حدیث مبارکہ سے قتل عمد اور قتل خطا کا اثبات ہوتا ہے۔ بعض اہل علم کا گمان ہے کہ قتل صرف دو ہی ہوتے ہیں قتل عمد اور قتل خطا، رہا قتل شبہ عمد تو وہ معروف نہیں، یہ امام مالک رحمہ اللہ کا قول ہے۔ امام ابو حنیفہ رحمہ اللہ نے قتل شبہ عمد پر دلیل سیدنا ابن عمر رضی اللہ عنہما کی حدیث مبارکہ سے حاصل کی ہے کہ کسی وزنی چیز سے کسی کو قتل کرنا قتل شبہ عمد ہوتا ہے اور اس میں قصاص واجب نہیں ہوتا (بلکہ دیت مغلظہ ہے) لیکن اس حدیث میں ان کے لیے کوئی حجت اور دلیل کا پہلو نہیں کیونکہ سیدنا ابن عمر رضی اللہ عنہما والی روایت میں کوڑے اور ڈنڈے کے ساتھ مارنے کا تذکرہ ہے جس سے عموماً خفیف ضرب ہی لگتی ہے اور اس سے قتل کا ارادہ نہیں ہوتا بلکہ صرف مارنے پیٹنے کا ارادہ ہوتا ہے، کوڑے اور ڈنڈے کا معاملہ بالعموم ایسا ہی ہوتا ہے۔ اگر اس کے باوجود ایسی ضرب سے کوئی بندہ مر جائے تو اسے قتل شبہ عمد کہتے ہیں، باقی رہا کسی بھاری اور وزنی چیز سے کسی کو مارنا (جیسا کہ امام ابو حنیفہ رحمہ اللہ کا قول ہے) تو اس کے ڈنڈے تو لوہے کے تیز دھار آلے سے ملتے اور مماثلت رکھتے ہیں جو بنایا ہی کسی کو قتل کرنے کے لیے کیا ہو۔","f":"اس صورت میں دیت کی تفصیل یوں ہوگی، بیس اونٹنیاں ایک سالہ، بیس اونٹنیاں دو سالہ، بیس نر اونٹ ایک سالہ، بیس تین سالہ اور بیس چار سالہ۔ یعنی وزنی چیز سے کسی کو مارنا قتل عمد کی ذیل میں آتا ہے قتل شبہ عمد کی ذیل میں نہیں آتا جیسا کہ امام ابو حنیفہ رحمہ اللہ سمجھتے ہیں۔ (ع، س)"}],[2541,"جناب ابن شہاب زہری، مکحول اور عطاء رحمہم اللہ بیان کرتے ہیں: ہم نے لوگوں کو اس بات پر پایا کہ ایک آزاد مسلمان کی دیت رسول اللہ صلی اللہ علیہ وسلم کے عہد اقدس میں سو اونٹ تھی، سیدنا عمر بن خطاب رضی اللہ عنہ نے اس دیت کا اندازہ دیہاتیوں کے لیے ایک ہزار دینار یا بارہ سو درہم مقرر کیا اور ایک آزاد دیہاتی مسلمان عورت کی دیت پانچ سو دینار یا چھ سو درہم مقرر فرمائی اور اگر وہ خاتون بادیہ نشین ہو تو اس کی دیت پچاس اونٹ ہے اور بادیہ نشین کو سونے اور چاندی کی ادائیگی کے لیے مجبور نہ کیا جائے، مسلمان آزاد عورت، جبکہ وہ دیہاتی لوگوں سے ہو، کی دیت پانچ سو دینار یا چھ ہزار درہم ہو گی، اگر اس کو قتل کرنے والا بھی بادیہ نشین ہو گا تو اس کی دیت پچاس اونٹ ہو گی، بادیہ نشین کو سونے اور چاندی کی تکلیف نہیں دی جائے گی۔","",{"k":"اسناده منقطع، ومسلم فيه ضعف: أخرجه الامام الشافعى في المسند: 1585، والبيهقى: 95/8","e":"امام بغوی رحمہ اللہ نے کہا: اہل علم کا دیت کے تقرر کے بارے میں اختلاف ہے کہ دراہم و دنانیر کی صورت میں کتنی مقدار ادا کی جائے، بعض اہل علم کا خیال ہے کہ دیت میں اصل اونٹ ہیں، اگر وہ دستیاب نہ ہوں تو جو کچھ بھی دیا جائے گا وہ اونٹوں کی قیمت کے مطابق دیا جائے گا۔ امام شافعی رحمہ اللہ کا قول جدید یہی ہے، اس موقف پر وہ روایت دلالت کرتی ہے جو جناب عمرو بن شعیب اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم قتل خطا میں دیہات والوں پر اونٹوں کی قیمت کے اعتبار سے دیت لاگو کرتے تھے، چار سو دینار یا اس کے مساوی چاندی، جب اونٹ مہنگے ہو جاتے تو آپ دیت کی قیمت بڑھا دیتے اور جب سستے ہو جاتے تو دیت کی قیمت کم کر دیتے۔ رسول اللہ صلی اللہ علیہ وسلم کے دور میں یہ قیمت چار سو دینار سے آٹھ سو دینار تک یا اس کے برابر آٹھ ہزار درہم رہی۔ (حسن، ابوداود: ۴۵۶۴، نسائی: ۴۸۱۵) امام شافعی رحمہ اللہ نے سیدنا عمر رضی اللہ عنہ کی حدیث مبارکہ جس میں دیت کے اونٹوں کی تعداد بارہ ہزار درہم مذکور ہے کا یہ مطلب بیان کیا ہے کہ ان کے زمانے میں اونٹ مہنگے ہو گئے ہوں گے اور ان کی قیمت ہزار دینار اور بارہ ہزار درہم تک پہنچ گئی ہو گی۔ امام شافعی رحمہ اللہ کے اس موقف کی تائید اس روایت سے ہوتی ہے جو جناب عمرو بن شعیب اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے دور میں دیت کی قیمت آٹھ سو دینار (سونے کی) یا آٹھ ہزار درہم (چاندی کے) تھی اور ان دنوں اہل کتاب کی دیت مسلمانوں کی دیت کے مقابلے میں آدھی ہوتی تھی، چنانچہ معاملہ ایسے ہی رہا حتی کہ سیدنا عمر رضی اللہ عنہ خلیفہ بنے تو انہوں نے خطبہ دیا اور کہا: بلاشبہ اونٹ مہنگے ہو گئے ہیں، پھر انہوں نے یہ دیت سونے والوں پر ایک ہزار دینار اور چاندی والوں پر بارہ ہزار دینار کر دی، گائے والوں کے لیے دو سو گائے اور بکریوں والوں کے لیے دو ہزار بکریاں، حلے (خاص قسم کے کپڑے) تیار کرنے والوں کے لیے دو سو حلے مقرر کی، اور ذمی کی دیت ویسے ہی رہنے دی اور اسے نہیں بڑھایا۔ (حسن، ابوداود: ۴۵۴۲) امام شافعی رحمہ اللہ نے اپنے قدیم قول میں اس اندازے کو پسند کیا ہے جو سیدنا عمر فاروق رضی اللہ عنہ نے اونٹوں کی عدم دستیابی اور مہنگے ہو جانے کی صورت میں مقرر فرمایا، انہوں نے اپنے زمانہ میں ہزار دینار اور بارہ ہزار درہم مقرر فرمائے۔ جناب عکرمہ سیدنا ابن عباس رضی اللہ عنہما سے بیان کرتے ہیں کہ بنو عدی کا ایک آدمی قتل ہو گیا تو نبی کریم صلی اللہ علیہ وسلم نے اس کی دیت بارہ ہزار (درہم) طے فرمائی۔ بعض اہل علم کا یہ موقف بھی ہے کہ دیت کی تین اصلیں ہیں: سو اونٹ، ہزار دینار یا بارہ ہزار درہم (چاندی)۔ جناب حسن بصری، عروہ بن زبیر، مالک، احمد اور اسحاق رحمہم اللہ سے اسی طرح مروی ہے جبکہ بعض کا خیال ہے کہ ایک شخص کی دیت سو اونٹ، ہزار دینار (سونا) یا دس ہزار درہم (چاندی) ہے، یہ قول سفیان ثوری، ابن شبرمہ اور امام ابو حنیفہ رحمہم اللہ کا ہے۔ ابو یوسف اور محمد نے کہا: دیت اونٹوں والوں پر ایک سو اونٹ، سونے والوں پر ایک ہزار دینار اور چاندی والوں پر دس ہزار درہم، گائے والوں پر دو سو گائے، بکریوں والوں پر دو ہزار بکریاں اور حلے (خاص قسم کے کپڑے) تیار کرنے والوں کے لیے دو سو حلے ہے۔ امام احمد اور اسحاق رحمہما اللہ نے بھی گائے اور بکریوں والوں پر یہی مقدار مقرر کی اور دیگر علماء نے دیت میں گائے، بکریاں اور حلے دینے کی بات نہیں کی۔ عورت کی دیت مرد کی دیت کی نصف ہے اسی طرح عورت کے اعضاء کی دیت بھی مرد کے اعضاء کی بہ نسبت آدھی ہے، اور قتل خطا کی دیت امام شافعی رحمہ اللہ کے نزدیک تین امور کی بنا پر مغلظہ ہو جاتی ہے، جب کوئی بلد حرام (حرمت والے شہر مکہ) میں کسی کو قتل کر دے یا حرمت والے مہینے میں یا کوئی اپنے محرم رشتہ دار کو قتل کر دے تو ان صورتوں میں وہی دیت ادا کرنا واجب ٹھہرے گا جو قتل شبہ عمد میں ادا کرنا ہوتی ہے اور یہی اصول اعضائے جسم کے عوضانے میں ملحوظ رکھا جائے گا اور جب عوضانہ دراہم و دنانیر کی صورت میں ادا کرنا ہو تو مذکورہ صدر تینوں صورتوں میں ایک ثلث زائد وصول کیا جائے گا۔ سیدنا عمر، سیدنا عثمان اور سیدنا ابن عباس رضی اللہ عنہم کا یہی موقف ہے، مروی ہے کہ ایک خاتون جسے مکہ میں روند ڈالا گیا تھا سیدنا عثمان رضی اللہ عنہ نے اس کے بارے میں فیصلہ کیا کہ مکمل دیت کے ساتھ ایک ثلث مزید وصول کیا جائے۔ اہل علم کی ایک جماعت کا خیال ہے کہ ان صورتوں میں بھی دیت مغلظہ وصول نہیں کی جائے گی۔ یہ اہل رائے کا موقف ہے۔ مروی ہے کہ جناب سعید بن مسیب اور سلیمان بن یسار سے دریافت کیا گیا کہ بلد حرام (حرمت والے شہر) میں دیت مغلظہ ہو جاتی ہے؟ تو ان دونوں نے کہا: نہیں لیکن اس جرم کی سنگینی ضرور بڑھ جاتی ہے۔ جناب سعید سے پوچھا گیا: کیا کسی کو زخمی کرنے سے بھی سنگینی میں اضافہ ہو جاتا ہے جس طرح کسی کو قتل کر دینے سے ہوتا ہے تو انہوں نے کہا: ’’جی ہاں‘‘"}],[2542,"جناب عبداللہ بن ابوبکر بن محمد بن عمرو بن حزم اپنے والد (ابوبکر) سے بیان کرتے ہیں کہ وہ مکتوب جو رسول اللہ صلی اللہ علیہ وسلم نے (سیدنا) عمرو بن حزم کو لکھا جس میں دیتوں کے احکام ومسائل تھے۔ اس میں تھا: ’’ایک جان کے قتل کی دیت سو اونٹ ہے اور ناک میں بھی پوری دیت ہے جبکہ اسے جڑ سے کاٹا گیا ہو، دفاع کے زخم اور پیٹ کے زخم میں ایک تہائی دیت ہے، ایک آنکھ، ایک ہاتھ اور ایک ٹانگ کی دیت پچاس اونٹ ہے اور ہر انگلی جو جڑ سے کاٹی جائے اس کی دیت دس اونٹ ہے، دانت کی دیت پانچ اونٹ ہے اور ایسے زخم میں جس سے ہڈی نظر آنے لگے پانچ اونٹ دیت ہے۔‘‘","",{"k":"صحيح وللحديث شواهد: أخرجه النسائى: 4868","e":"(أُوعِيَ جَدْعًا) اور ایک روایت میں (أُوْعِبَ جَدْعًا) کے الفاظ مروی ہیں۔ دونوں کے معنی جڑ سے کاٹے جانے کے ہیں۔"}],[2543,"سیدنا ابن عباس رضی اللہ عنہما سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’یہ اور یہ (دیت میں) برابر ہیں‘‘ اور آپ نے چھنگلی اور انگوٹھے کی طرف اشارہ کیا۔","",{"k":"أخرجه البخارى: 6895","e":"سیدنا ابن عباس رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تمام انگلیاں برابر ہیں، تمام دانت برابر ہیں، ثنیہ (اوپر اور نیچے کے درمیانی دو دانت) اور داڑھ برابر ہے۔‘‘ (صحیح، ابوداود: ۴۵۵۹، ابن ماجہ: ۲۶۵۰) سیدنا ابن عباس رضی اللہ عنہما نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے ہاتھوں اور پاؤں کی انگلیوں کی دیت برابر قرار دی ہے۔ (صحیح، ابوداود: ۴۵۶۱، ترمذی: ۱۳۹۱)"}],[2544,"سیدنا ابو موسیٰ اشعری رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’انگلیاں سب برابر ہیں۔‘‘ میں نے عرض کیا: ہر انگلی کے دس دس اونٹ ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’ہاں۔‘‘","",{"k":"صحيح: أخرجه ابوداود: 4557، والنسائى: 4859، وابن ماجه: 2654","e":"ابو الولید نے شعبہ کے بعد مسروق بن ایاس کا نام ذکر کیا ہے۔","f":"انگلیاں ہاتھ کی ہوں یا پاؤں کی، انگوٹھا یا چھنگلیا وغیرہ سبھی برابر ہیں، ہر ایک میں دس دس اونٹ دیت ہے۔"}],[2545,"عمرو بن شعیب عن ابیہ عن جدہ کی سند سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’جن زخموں سے ہڈی ظاہر ہو جائے ان میں پانچ پانچ اونٹ (دیت) ہے اور دانتوں میں پانچ پانچ اونٹ ہے اور انگلیوں میں دس اونٹ ہے۔‘‘","",{"k":"حسن صحيح: أخرجه ابوداود: 4562، وابن ماجه: 2653، والنسائى: 4850","e":"امام بغوی رحمہ اللہ نے کہا: ایک انسان کے جسم کے تیرہ اعضاء ایسے ہیں جن کو کاٹنے پر مکمل دیت ادا کرنا پڑتی ہے۔ (۱)...... ناک کا نرم کنارہ: اگر کوئی ناک کا پورا نرم کنارہ کاٹ دے تو اسے پوری دیت ادا کرنا ہو گی اور وہ ہے سو اونٹ۔ ایک طرف کے نرم حصے کو کاٹ ڈالنے کی صورت میں آدھی دیت ادا کرنا ہو گی، ناک کا سرا کوئی جتنا کاٹے گا اس کی مقدار کے مطابق دیت ادا کرنا ہو گی۔ سیدنا زید بن ثابت رضی اللہ عنہ نے کہا: ناک کی نوک کاٹنے میں ایک تہائی دیت ہے۔ امام مجاہد، مکحول، احمد اور اسحاق رحمہم اللہ کا یہی قول ہے۔ بعض اہل علم کا کہنا ہے، ناک کا بانسہ (نرم کنارہ) کاٹنے میں آدھی دیت ہے۔ سیدنا زید رضی اللہ عنہ سے مروی ہے کہ انہوں نے کہا: ناک کے نتھنوں کے درمیان کی دیوار کاٹنے پر ایک تہائی دیت واجب ہوتی ہے۔ الوترہ، سے مراد ناک کے نتھنوں کی درمیانی دیوار ہے۔ (۲)...... دونوں آنکھوں کی پلکیں: (بالائی اور تحتانی) کاٹنے کی صورت میں مکمل دیت (سو اونٹ) ادا کرنا واجب ہے۔ ایک آنکھ کی دونوں پلکیں کاٹنے کی صورت میں آدھی دیت پڑتی ہے اور ایک پلک کاٹنے کی صورت میں چوتھائی دیت یعنی پچیس اونٹ کی ادائیگی لازم آتی ہے۔ جفن سے مراد پوٹے ہیں جن سے آنکھوں کو بند کیا جاتا ہے۔ (۳)...... دونوں کان: کسی کے دونوں کان کاٹ دینے کی صورت میں پوری دیت کی ادائیگی لازم آتی ہے اور ایک کان کاٹ دینے کی صورت میں آدھی دیت ہے۔ (۴)...... دونوں ہونٹ: دونوں ہونٹ کاٹ دینے کی صورت میں پوری دیت ہے اور ان میں سے ایک پر نصف دیت ہے، دیت کے ضمن میں بالائی اور تحتانی ہونٹ برابر ہیں اگر چہ ان میں سے ایک ہونٹ (اوپر والا) زیادہ بدنمائی اور بدصورتی کا موجب ہے، ان کا معاملہ ہاتھوں کی طرح ہے، دونوں ہاتھوں کی دیت یکساں ہے حالانکہ دائیاں ہاتھ منفعت اور فائدے میں فائق تر ہے۔ جناب سعید بن مسیب نے کہا: نچلا ہونٹ کاٹنے کی صورت میں دیت دو تہائی ہو گی۔ الشفتان سے مراد ہونٹ ہیں جو گولائی میں اوپر اور نیچے سے دانتوں کو چھپا لیتے ہیں اور الگ الگ ہونے کی صورت میں دانت ظاہر اور عیاں ہو جاتے ہیں۔ (۵)...... زبان: مکمل زبان کاٹنے کی صورت میں پوری اور کامل دیت ادا کرنا ہو گی۔ (۶)...... منہ کے تمام دانت: پورے دانت یعنی بتیس نکال دینے کی صورت میں کامل دیت ادا کرنا ہو گی جبکہ اکیلے دانت کی دیت پانچ اونٹ ہے۔ (۷)...... دونوں جبڑے: دونوں جبڑے نکال دینے کی صورت میں پوری دیت ہے اور ایک جبڑے کی دیت آدھی ہے۔ اگر کوئی جبڑے دانتوں سمیت نکال دے تو اس پر جبڑے اور دانتوں دونوں کی دیت پڑے گی۔ یاد رہے! ایک دانت کی دیت پانچ اونٹ ہے۔ (۸)...... دونوں ہاتھ: دونوں ہاتھ کاٹ دینے کی صورت میں پوری دیت ہے اور ایک ہاتھ کاٹنے کی صورت میں آدھی دیت۔ ایک انگلی کی دیت دس اونٹ ہے، پاؤں کی انگلیوں کا بھی یہی حساب ہے۔ انگلی کے ایک پور کی دیت انگلی کی دیت کا ثلث (۱/۳) ہے ماسوائے انگوٹھے کے پور کے کہ اس میں انگلی کی دیت کا نصف لازم آتا ہے (یعنی پانچ اونٹ) اس لیے کہ انگوٹھے کے دو پور ہی تو ہوتے ہیں دیت کے باب میں پاؤں اور ہاتھوں کی انگلیوں کے درمیان میں کوئی فرق نہیں۔ (۹)...... دونوں ٹانگیں: دونوں ٹانگیں کاٹ دینے کی صورت میں مکمل دیت لازم آتی ہے اور ایک میں آدھی دیت۔ (۱۰)...... دونوں سرین: دونوں سرین کاٹ دینے کی صورت میں پوری دیت کی ادائیگی لازم آتی ہے خواہ ہڈی ننگی نہ بھی ہوئی ہو، ایک سرین کاٹ دینے کی صورت میں آدھی دیت پڑتی ہے۔ الألیتَان سے مراد کمر کے آخر سے لے کر ران کے شروع ہونے تک کا ابھرا ہوا گوشت، جس پر انسان بیٹھتا ہے۔ اسے فارسی میں سرین (چوتر) کہتے ہیں۔ (۱۱)...... آلہ تناسل کی سپاری: اس کو کاٹ دینے پر بھی پوری دیت کی ادائیگی لازم آتی ہے اور اگر سپاری کا کچھ حصہ کاٹ دیا جائے تو کٹے ہوئے حصے کے حساب سے دیت ادا کرنا ہو گی۔ (۱۲)...... خُصیَتین: کاٹ دینے کی صورت میں پوری دیت لازم آتی ہے اور ایک گولی نکال دینے کی صورت میں آدھی دیت۔ اس میں دائیں اور بائیں کی کوئی قید نہیں جس طرح ہاتھوں اور پاؤں کا معاملہ ہے کہ ان میں بھی داہنے اور بائیں کا کوئی فرق نہیں۔ (۱۳)...... کمر کی ریڑھ کی ہڈی: اگر کوئی شخص دوسرے کی ریڑھ کی ہڈی توڑ دے جس سے اس کا چلنا پھرنا موقوف ہو جائے تو توڑنے والے پر پوری دیت کی ادائیگی لازم ٹھہرتی ہے۔ اگر کسی نے دوسرے شخص کے ہاتھ، پاؤں، ذکر، کان، آنکھوں کے کوے، زبان اور ہونٹوں پر کوئی چیز ماری جس سے مذکورہ صدر اعضاء میں سے کوئی ایک شل ہو گیا اور اس نے اپنا کام کرنا چھوڑ دیا تو اس کا حکم اس عضو کو کاٹ دینے کا ہی ہے، یعنی جو دیت اس عضو کو کاٹ دینے کی صورت میں پڑتی ہے وہی دیت شل کر دینے کی صورت میں پڑتی ہے۔ اگر کوئی دوسرے کو ایسی ضرب مارے جس سے اس کا عقل و شعور جاتا رہے تو مارنے والے پر پوری دیت ہے۔ اسی طرح اگر کسی کے مارنے سے دوسرے کی بصارت، سماعت، سونگھنے کی قوت، چکھنے کی صلاحیت یا گفتگو کی صلاحیت ختم ہو جائے اس طرح کہ وہ بے چارہ ایک لفظ نہ بول سکے تو مارنے والے پر پوری دیت کی ادائیگی لازم آئے گی، ایک آنکھ کی بصارت ضائع ہونے ایک کان کی شنوائی ختم ہونے کی صورت میں آدھی دیت ہے، خواہ مضروب کا دوسرا عضو صحیح سلامت ہو یا نہ۔ امام مالک رحمہ اللہ نے کہا: جب کوئی کانے شخص کی صحیح آنکھ کو پھوڑ دے تو اس پر پوری دیت پڑے گی۔ امام زہری رحمہ اللہ کا بھی یہی قول ہے، سیدنا ابن عمر رضی اللہ عنہما اور جناب سلیمان بن یسار رحمہ اللہ سے بھی اسی طرح مروی ہے۔ کسی خاتون کے دونوں ابرو کاٹ ڈالنے کی صورت میں پوری دیت ہے اور ایک کاٹ دینے کی صورت میں آدھی ہے، عورت کے پستانوں کے دونوں سروں کو کاٹ دینے کی صورت میں پوری دیت ہے اور ایک کو کاٹ دینے کی صورت میں آدھی دیت ہے۔ مرد کے پستان کے دونوں سروں کو کاٹ ڈالنے کے متعلق دو قول ہیں ایک تو یہ کہ پوری دیت لازم آتی ہے جس طرح عورت کے پستانوں کو معاملہ ہے، دوسرا قول یہ ہے کہ ان میں دیت واجب نہیں ہوتی بلکہ جرمانہ اور تاوان لازم آتا ہے، کیونکہ مرد کے پستان اپنے اندر کچھ افادہ نہیں رکھتے جبکہ عورت کے پستانوں میں بچے کو دودھ پلانے کی منفعت ہے۔ جب تک سیدنا عمر فاروق رضی اللہ عنہ کو دیت میں انگلیوں کی برابری والی حدیث نہیں پہنچی تھی تو حضرت انگلیوں کی دیت میں ان کی منفعت کو پیش نظر رکھتے ہوئے فرق کرتے تھے مثلاً انگوٹھے میں بطور دیت پندرہ اونٹوں کا حکم کرتے، درمیانی انگلی اور انگشت شہادت میں دس اونٹوں کا، بنصر (چھنگلی کے ساتھ والی) میں نو اونٹوں کا اور خنصر (چھنگلی) میں چھ کا۔ ان کے دور میں فیصلے اسی طرح ہوتے رہے یہاں تک کہ انہوں نے وہ خط ملاحظہ کیا جو آپ صلی اللہ علیہ وسلم نے سیدنا عمرو بن حزم کو تحریر کیا تھا جس میں رقم تھا: «إِنَّ فِي كُلِّ أُصْبُعٍ عَشْرًا مِنَ الْإِبِلِ»...... ’’بلاشبہ ہر انگلی کی دیت دس اونٹ ہے۔‘‘ (سندہ ضعیف، مسند شافعی: ۹۸۰) (لیکن شرعی مسئلہ ایسے ہی ہے کہ انگلی کی دیت دس اونٹ ہے۔) حدیث مبارکہ ملنے کے بعد سیدنا عمر رضی اللہ عنہ نے اسی کو دستور العمل بنا لیا۔ اسی طرح آپ سامنے کے دانتوں میں پانچ پانچ اونٹوں کا فیصلہ کرتے تھے اور داڑھوں میں ایک ایک اونٹ کا۔ اہل علم کا اس بات پر اتفاق ہے کہ ہاتھوں اور پاؤں کی انگلیوں کی دیت برابر ہے اور یہ کہ ہر انگلی کی دیت دس اونٹ ہے۔ اسی طرح تمام دانتوں کی دیت برابر ہے جس طرح اہل علم کا اس امر میں اتفاق ہے کہ چھوٹے بچے اور بڑے آدمی نیز کمزور و لاغر اور قوی و صحت مند کی دیت یکساں ہے۔ امام بغوی رحمہ اللہ نے کہا: سر اور چہرے میں دس قسم کے زخم ہو سکتے ہیں۔ (۱)...... الْحَارِصَة: اس سے مراد وہ معمولی زخم ہے جو تھوڑا سا کھال کو چیر دیتا ہے اور خراش لگا دیتا ہے، یعنی رگڑ۔ جب دھوبی کپڑا دھلائی کے وقت پھاڑ دے تو کہا جاتا ہے: حرص القصار الثوب۔ (۲)...... الدَّامِيَة: ایسا زخم جس سے خون بہہ پڑے۔ (۳)...... الْبَاضِعَة: ایسا چر کہ جس سے جلد پھٹ جائے اور چر جائے۔ (۴)...... الْمُتَلَاحِمَة: ایسا زخم جو گوشت میں ذرا گہرا اتر جائے۔ (۵)...... الْمُلْطَاة: ایسا زخم جو اس جھلی تک پہنچ جائے جو گوشت اور ہڈی کے درمیان ہوتی ہے اسے سمحاق بھی کہتے ہیں۔ ان پانچ قسم کے زخموں میں جرمانہ اور ہرجانہ ہے دیت نہیں (جسے شارح نے حکومت کے لفظ سے تعبیر کیا ہے لفظ حکومت کی وضاحت دسویں زخم کی تفصیل کے بعد ملاحظہ کریں۔) (۶)...... الْمُوَضِّحَة: ایسا زخم جو ہڈی کو نہ توڑے لیکن اسے ظاہر کر دے، ایسے زخم میں پانچ اونٹ دیت واجب ہوتی ہے زخم چھوٹا ہو خواہ بڑا۔ اگر ایسا زخم سر اور چہرے پر مختلف جگہ پر لگ جائے اور زخم الگ الگ ہو تو ہر زخم کے بدلے پانچ، پانچ اونٹوں کی ادائیگی لازم آئے گی۔ امام مالک رحمہ اللہ نے کہا: نچلے جبڑے اور ناک کو میں سر میں داخل نہیں سمجھتا ان پر لگے زخم کو الگ شمار کیا جائے گا کیونکہ یہ دونوں الگ ہڈیاں (اعضاء) ہیں۔ (۷)...... الْهَاشِمَة: ہڈی توڑ دینے والا زخم، اس میں بطور دیت دس اونٹ واجب ہوتے ہیں، اگر ہڈی تو ٹوٹ جائے مگر ظاہر نہ ہو تو پھر پانچ اونٹ ہی واجب ہوں گے۔ (۸)...... الْمُنَقِّلَة: وہ زخم جو ہڈی کو اپنی جگہ سے ہلا دے، اس میں بطور دیت پندرہ اونٹوں کی ادائیگی واجب ہے۔ (۹)...... الْمَأْمُومَة: ایسا زخم جو دماغ تک پہنچ جائے (یعنی دماغ اور زخم کے درمیان صرف باریک جھلی حائل ہو) اسے آمَّۃ بھی کہتے ہیں کیونکہ ایسا زخم ام الرأس تک پہنچ جاتا ہے اس میں ایک تہائی دیت ہے۔ (۱۰)...... الدَّامِغَة: دماغ تک پہنچنے والا زخم جس سے آدمی مر جاتا ہے اور اس کے بعد عموماً زندہ رہنا محال ہوتا ہے ایسے زخم میں مکمل دیت ہے۔ (۱۱)...... الْجَائِفَہ: اس میں ایک تہائی دیت ہے اور اس سے مراد ایسا زخم ہے جو پیٹ تک پہنچ کر اس میں داخل ہو جائے خواہ بواسطہ پشت ہو یا پیٹ یا سینہ۔ اگر ایسا زخم دوسری طرف سے بھی ظاہر ہو جائے تو یہ دو زخم متصور ہوں گے اور دونوں میں دو ثلث (دو تہائی یعنی ۲/۳) دیت ہو گی۔ یاد رہے کہ اگر مُوَضِّحَة قسم کا زخم سر اور چہرے کے علاوہ کسی اور جگہ پر لگ جائے تو دیت نہیں بلکہ حکومت (جرمانہ) ہے اسی طرح اگر کوئی شخص دوسرے کی دانت کے علاوہ کوئی ہڈی توڑ دے مثلاً پسلی یا ہنسلی وغیرہ یا ناکارہ اور شل ہاتھ یا گونگی زبان یا ناکارہ ڈیلا یا زائد انگلی (چھٹی) یا زائد اور ناہموار دانت توڑ دے تو ان صورتوں میں دیت نہیں حکومت ہے۔ مروی ہے کہ سیدنا عمر رضی اللہ عنہ نے ہنسلی اور پسلی میں ایک اونٹ دیت کا فیصلہ کیا تھا اور سیدنا زید بن ثابت رضی اللہ عنہ کہا کرتے تھے کہ اپنی جگہ قائم (مگر ناکارہ) آنکھ میں ایک سو دینار ہیں۔ یہ سب باتیں بصورت حکومت ہیں اور حکومت یہ ہے کہ ایک محتاط اندازہ لگایا جائے کہ اگر بالفرض مجروح شخص غلام ہوتا تو اس عضو کے ناکارہ ہونے کی وجہ سے اس کی قیمت میں کتنی کمی ہوتی، جتنی کمی کا امکان ہو اتنی رقم بطور جرمانہ مجرم پر ڈال دی جائے۔ حکومت یعنی جرمانے کا تعین کرتے وقت اس بات کا دھیان رہے کہ اس عضو کا جرمانہ، شریعت میں اس عضو کی مقرر کردہ دیت سے کہیں بڑھ نہ جائے مثلاً اگر کسی نے دوسرے کے سر میں ایسا زخم لگا دیا جو موضحہ سے کم ہے تو اس کا جرمانہ موضحہ کی دیت (یعنی پانچ اونٹوں) سے بڑھنا نہیں چاہیے زخم خواہ کتنا ہی عیب دار کر دینے والا کیوں نہ ہو۔ جناب سعید بن مسیب نے کہا: کسی عضو میں لگنے والا ایسا زخم جو آر پار ہو جائے اس میں اس عضو کی دیت کا ثلث ہے۔ اگر کوئی شخص دوسرے کی ایسی ہتھیلی کاٹ دے جس پر پہلے سے ہی انگلیاں نہ ہوں تو ایسی ہتھیلی کاٹنے سے دیت نہیں بلکہ حکومت (جرمانہ) واجب ہوتی ہے۔ اگر کوئی آدمی دوسرے شخص کا تندرست و توانا ہاتھ کلائی سے کاٹ دیتا ہے تو ہتھیلی کا ہرجانہ (حکومت) انگلیوں کی دیت میں ہی آ جائے گا۔ امام شافعی رحمہ اللہ کے اصحاب (شاگردوں) میں ابو عبید بن حرب نے کہا: اس وقت تک ہاتھ میں نصف دیت واجب نہیں ہوتی جب تک کہ وہ کندھے سے کٹا ہوا نہ ہو۔ لیکن عام اہل علم کا موقف ان کے برعکس ہے۔ اسی طرح اگر کوئی شخص دوسرے کا انگلیوں سے محروم قدم کاٹ دے تو اس میں دیت نہیں بلکہ حکومت ہے اور اگر وہ قدم مکمل ہے تو اس کے کاٹنے میں دیت ہے (یعنی ایک انگلی میں دس اونٹ) اور قدم کا ہرجانہ انگلیوں کی دیت کے اندر ہی ہے۔ اگر کوئی شخص دوسرے کا ہاتھ کہنی سے یا ٹانگ گھٹنے سے کاٹ دے تو ایسی صورت میں متعلقہ عضو کی دیت کے ساتھ ساتھ کلائی اور پنڈلی کا تاوان بھی وصول کیا جائے گا۔ مروی ہے کہ سیدنا عمر فاروق رضی اللہ عنہ نے کہا: شل اور ناکارہ ہاتھ کی دیت، ہاتھ کی دیت کا ثلث ہے۔ امام مجاہد، احمد اور اسحاق رحمہم اللہ کا یہی قول ہے۔ سیدنا عمر رضی اللہ عنہ سے یہ بھی مروی ہے کہ انہوں نے کہا: وہ آنکھ جو اپنی جگہ قائم رہے (یعنی ناکارہ ہو کر اپنی جگہ برقرار رہے) اس میں ایک تہائی دیت ہے، امام اسحاق رحمہ اللہ کا بھی یہی قول ہے۔ مروی ہے کہ سیدنا عمر فاروق رضی اللہ عنہ نے ہنسلی کی ہڈی توڑ دینے پر ایک اونٹ کا فیصلہ کیا۔ اسی طرح پسلی ٹوٹ جانے پر بھی ایک اونٹ کا فیصلہ کیا۔ یہ بھی کہا گیا ہے کہ سیدنا عمر رضی اللہ عنہ نے ہنسلی اور پسلی میں ایک اونٹ کا جو فیصلہ کیا ہے وہ بطور حکومت (تاوان) کے کیا ہے نہ کہ شریعت کے مقرر کردہ بدل کے طور پر۔ اکثر اہل کے نزدیک عورت کے اعضاء کی دیت مرد کے اعضاء کی دیت سے نصف ہے۔ مروی ہے کہ جناب سعید بن مسیب رحمہ اللہ نے کہا: عورت اور مرد کی دیت کل دیت کے ایک ثلث تک برابر ہے، (یعنی ثلث تک مرد کی طرح ہے اس کے بعد نہیں) عروہ بن زبیر اور امام زہری نے اسی کے مثل کہا ہے۔ جب دیت ایک ثلث تک پہنچ جائے تو اس صورت میں عورت کی دیت مرد کی دیت سے نصف ہے حتیٰ کہ ان کا کہنا ہے عورت کی تین انگلیوں کی دیت تیس اونٹ ہے اور چار انگلیوں کی دیت بیس اونٹ ہے، سیدنا عمر فاروق اور سیدنا زید بن ثابت رضی اللہ عنہما سے مروی ہے کہ عورت اور مرد کی دیت ایک ثلث تک برابر ہے جب ثلث سے زائد دیت لاگو ہو تو اس میں مرد کی دیت سے نصف ہے۔ غلام کے اعضاء کا بدل اس کی قیمت کے حساب سے ہے مثلاً اگر کوئی شخص کسی غلام کا ایک ہاتھ کاٹ دیتا ہے تو اس پر غلام کی قیمت کا نصف ادا کرنا واجب ٹھہرے گا اور اگر دونوں ہاتھ کاٹ دیتا ہے تو اس غلام کی مارکیٹ کے حساب سے مکمل قیمت ادا کرنا ہو گی۔ جناب سعید بن مسیب، سلیمان بن یسار، شافعی اور اہل رائے کا یہی موقف ہے، اس مسئلے میں بعض اہل علم کا یہ بھی خیال ہے کہ اعضاء کے قطع و برید کی صورت میں غلام کی قیمت جتنی گری اور کم ہوئی ہو اتنی رقم ادا کرنا ہو گی جیسا کہ یہی اصول جانوروں میں کارفرما ہے۔ امام مالک رحمہ اللہ نے کہا: غلام کو اگر موضحہ (ہڈی کو توڑے نہ لیکن ظاہر کر دے) زخم لگے تو زخم لگانے والے پر اس کی قیمت کا بیسواں حصہ (یعنی ۱/۲۰) ہے اور منقلہ زخم لگنے کی صورت میں اس کی قیمت کا دسواں اور بیسواں دو قیمتیں ہیں۔ اور مأمومہ اور جائفہ زخم لگنے میں اس کی قیمت کا ایک تہائی ادا کرنا ہو گا۔ مذکورہ صدر چار زخموں کے علاوہ میں اتنا تاوان ہے جس قدر زخم لگنے سے غلام کی قیمت کم ہوئی ہو۔","f":"لفظ حکومت ایک خاص اصطلاح ہے، ہر جگہ اصطلاح کی تعریف اور وضاحت چونکہ ممکن نہیں ہوتی اس لیے شرح السنة میں اس لفظ کا معنی تاوان، جرمانہ اور ہرجانہ کے الفاظ سے کیا گیا ہے اور یہ بھی جرمانے کے تعین کا ایک اندازہ ہے اس لیے سہولت کے لیے یہی الفاظ استعمال کیے گئے ہیں۔ (ع، س)"}]])